// js/statRegistry.js
// 📊 屬性註冊表 —— 遊戲引擎支援的全部屬性鍵
//
// ⭐ 目的：
//   原本 characterSystem.addBonus() 只認得 8 個屬性，
//   導致 PoE 的 200+ 詞綴有 92% 無處可放。
//   本檔案定義完整屬性表，讓 addBonus 變成資料驅動。
//
// ⭐ 分組邏輯：
//   core      — 核心八維（原有）
//   offense   — 攻擊相關
//   defense   — 防禦相關
//   resist    — 抗性
//   resource  — 續航
//   speed     — 速度
//   mechanic  — 機制（召喚物/圖騰/光環等）
//   utility   — 掉落與實用
window.HY = window.HY || {};
(function () {
    'use strict';

    /* ══════════════════════════════════════════
       屬性定義
       ══════════════════════════════════════════
       key   : 屬性鍵（詞綴 statMod 對應）
       name  : 中文顯示名
       group : 分組
       pct   : true = 百分比型（UI 顯示 %）
       cap   : 上限（null = 無上限）
       desc  : 說明
    */
    var STATS = {
        /* ── 核心八維（原有，不可移除） ── */
        atk:      { name: '外功攻擊',   group: 'core', pct: false, cap: null },
        def:      { name: '護體防禦',   group: 'core', pct: false, cap: null },
        maxHp:    { name: '最大氣血',   group: 'core', pct: false, cap: null },
        maxMp:    { name: '最大內力',   group: 'core', pct: false, cap: null },
        hit:      { name: '精準命中',   group: 'core', pct: false, cap: 95 },
        eva:      { name: '輕功閃避',   group: 'core', pct: false, cap: 85 },
        crit:     { name: '會心爆擊',   group: 'core', pct: false, cap: 90 },
        critRes:  { name: '暴擊抵抗',   group: 'core', pct: false, cap: null },

        /* ── 攻擊 ── */
        atkPct:       { name: '攻擊傷害',   group: 'offense', pct: true },
        physDmg:      { name: '外功傷害',   group: 'offense', pct: true },
        elemDmg:      { name: '九元素內勁', group: 'offense', pct: true },
        /* ⚠️ 已移除（戰鬥中從不讀取，且與八元素攻重複）：
              fireDmg / coldDmg / lightningDmg / chaosDmg
              → 單元素傷害改由 elementSystem 的九元素攻擊值呈現，
                詞條「火勁傷害 +31%」會直接乘在該元素的攻擊力上
                （通道：elemAtk_fire / elemAtk_ice / ...）。
              玩家在「🌀 九元素」區就能看到實際的攻/抗，
              不需要再用另一組百分比欄位重複表達同一件事。 */
        critDmg:      { name: '爆擊傷害',   group: 'offense', pct: true },
        critFlat:     { name: '爆擊率加成', group: 'offense', pct: true },
        hitFlat:      { name: '命中率加成', group: 'offense', pct: true },
        armorPen:     { name: '護甲穿透',   group: 'offense', pct: true, cap: 85 },
        /* ⭐ v459：持續傷害（DoT）機制已移除 —— 屬性整條刪除 */

        /* ── 防禦 ── */
        armorPct:     { name: '護甲加成',   group: 'defense', pct: true },
        evaPct:       { name: '閃避加成',   group: 'defense', pct: true },
        blockChance:  { name: '格擋率',     group: 'defense', pct: true, cap: 75 },
        dodgeChance:  { name: '躲避率',     group: 'defense', pct: true, cap: 75 },
        dmgReduce:    { name: '受傷減免',   group: 'defense', pct: true, cap: 75 },
        /* ⭐⭐ v488：罡氣（esShield）與罡氣加成（esPct）已移除登錄
           ──────────────────────────────────────────────────────────
           罡氣／護盾機制已於 v482 完整下架，但屬性註冊表還留著這兩項，
           導致「詳細戰鬥與抗性面板」的防禦區仍列出
           「罡氣：0」「罡氣加成：0」—— 這兩個數字永遠是 0，
           玩家看了只會困惑「這是不是壞了」。

           移除登錄後，面板不再為它們產生格子（key 不在 STATS 就不會被渲染）。
           ⚠️ 只刪註冊，不動 derived 上的欄位計算 ——
              其他地方若還讀 d.esShield 仍然拿得到 0，不會出現 undefined。 */
        thornsDmg:    { name: '反傷',       group: 'defense', pct: true },

        /* ── 抗性 ──
           ⭐ v461：POE 四抗（火/冰/電/混沌）已完全移除。
           抗性改由「九元素防禦值（elDef_*）」直接提供，
           UI 顯示在「🌀 九元素」區塊，不再有第二套抗性欄位。
           唯一保留的是 maxAllRes（九元素共同上限），因為上限仍需要詞條調整。 */
        maxAllRes:    { name: '九元素抗性上限', group: 'resist', pct: true },

        /* ── 續航 ── */
        lifeRegen:    { name: '氣血回復',   group: 'resource', pct: true },
        manaRegen:    { name: '內力回復',   group: 'resource', pct: true },
        lifeLeech:    { name: '氣血偷取',   group: 'resource', pct: true },
        manaLeech:    { name: '內力偷取',   group: 'resource', pct: true },
        lifeOnHit:    { name: '擊中回血',   group: 'resource', pct: false },
        manaOnHit:    { name: '擊中回內',   group: 'resource', pct: false },
        lifeOnKill:   { name: '擊殺回血',   group: 'resource', pct: false },
        hpCostReduce: { name: '生命消耗減免', group: 'resource', pct: true },
        mpCostReduce: { name: '內力消耗減免', group: 'resource', pct: true },

        /* ── 速度 ── */
        atkSpd:       { name: '攻擊速度',   group: 'speed', pct: true },
        castSpd:      { name: '施法速度',   group: 'speed', pct: true },
        moveSpd:      { name: '移動速度',   group: 'speed', pct: true, cap: 200 },
        atbGain:      { name: '集氣速度',   group: 'speed', pct: true },
        cooldownRec:  { name: '冷卻回復',   group: 'speed', pct: true },

        /* ── 武魂／召喚物（舊 POE Minion 詞詞條，靈寵系統已改武魂） ── */
        minionDmg:    { name: '武魂傷害',   group: 'minion', pct: true },
        minionHp:     { name: '武魂氣血',   group: 'minion', pct: true },
        minionSpd:    { name: '武魂速度',   group: 'minion', pct: true },

        /* ⚠️ aoeRadius（招式範圍）已移除：
              derived stats 中永遠是 undefined —— 沒有任何詞條會寫入它。
              群攻加成實際走「門派機制」的 mods.aoeBonus（只有唐門用到），
              那是比例值直接乘在傷害上，與這個屬性欄位無關。
              面板顯示「招式範圍：—」只會讓玩家誤以為有點可加。 */

        /* ⚠️ 已移除（本作沒有對應機制，戰鬥中從不讀取，顯示只是誤導）：
              totemDmg     圖騰傷害      → 本作是劍樁，走門派機制不走屬性
              auraEffect   光環效果      → 本作沒有光環技能
              curseEffect  詛咒效果      → 本作是陰煞，走門派機制
              projSpeed    投射物速度    → 本作沒有投射物系統
              projCount    額外投射物    → 同上
              pierceCount  穿透次數      → 同上
              chainCount   連鎖次數      → 同上
              skillEffectDur 技能持續    → 本作招式沒有可調持續時間
              lightRadius  視野範圍      → 本作沒有迷霧/視野機制
           這些詞條若出現在裝備/天賦上，會被 wuxiaPurge 一併過濾。 */

        /* ── 掉落與實用 ── */
        itemRarity:   { name: '物品稀有度', group: 'utility', pct: true },
        itemQuantity: { name: '物品數量',   group: 'utility', pct: true },
        goldFind:     { name: '銀兩獲取',   group: 'utility', pct: true },
        expGain:      { name: '經驗獲取',   group: 'utility', pct: true },
        mapDropRate:  { name: '地圖掉落率', group: 'utility', pct: true },
        essenceRate:  { name: '精隨掉落率', group: 'utility', pct: true }

        /* ⚠️ lightRadius（視野範圍）已移除：本作沒有迷霧／視野機制，
              這個屬性在戰鬥中從不被讀取，顯示只是誤導。 */
    };

    /* 屬性鍵陣列（供快速迭代） */
    var STAT_KEYS = Object.keys(STATS);

    /* 分組中文名 */
    var GROUP_NAMES = {
        core:     '⚔️ 核心屬性',
        offense:  '🔥 攻擊',
        defense:  '🛡️ 防禦',
        /* ⚠️ resist 分組不顯示（抗性統一由「🌀 九元素」區呈現） */
        resource: '💚 續航',
        speed:    '⚡ 速度',
        minion:   '🌌 武魂',
        utility:  '💰 實用'
    };

    /* ══════════════════════════════════════════
       工具函式
       ══════════════════════════════════════════ */
    function statInfo(key) { return STATS[key] || null; }

    /** 屬性圖鑑 key → 中文名（延遲建立） */
    var _codexNameIdx = null;
    function codexNameIndex() {
        if (_codexNameIdx) return _codexNameIdx;
        _codexNameIdx = {};
        var C = window.HY && window.HY.Data && window.HY.Data.STAT_CODEX;
        if (C && C.groups) {
            C.groups.forEach(function (g) {
                (g.stats || []).forEach(function (s) {
                    if (s && s.key) _codexNameIdx[s.key] = s.name || s.abbr || s.key;
                });
            });
        }
        var alias = {
            hpRegen: 'lifeRegen', mpRegen: 'manaRegen', thorns: 'thornsDmg',
            penetration: 'armorPen'
        };
        Object.keys(alias).forEach(function (from) {
            if (_codexNameIdx[from] && !_codexNameIdx[alias[from]]) {
                _codexNameIdx[alias[from]] = _codexNameIdx[from];
            }
            if (_codexNameIdx[alias[from]] && !_codexNameIdx[from]) {
                _codexNameIdx[from] = _codexNameIdx[alias[from]];
            }
        });
        return _codexNameIdx;
    }

    function statName(key) {
        if (!key) return '';
        var s = STATS[key];
        if (s) return s.name;
        var idx = codexNameIndex();
        if (idx[key]) return idx[key];
        var mDef = /^elDef_(.+)$/.exec(key);
        if (mDef) {
            if (mDef[1] === 'all') return '九元素抗性';
            var D = window.HY && window.HY.Data;
            var em = D && D.ELEMENTS && D.ELEMENTS[mDef[1]];
            if (em && em.name) return em.name + '元素抗性';
            return (idx[key] || '元素抗性');
        }
        var mAtk = /^elAtk_(.+)$/.exec(key);
        if (mAtk) {
            if (mAtk[1] === 'all') return '全元素攻擊';
            var D2 = window.HY && window.HY.Data;
            var em2 = D2 && D2.ELEMENTS && D2.ELEMENTS[mAtk[1]];
            if (em2 && em2.name) return em2.name + '元素攻擊';
            return (idx[key] || '元素攻擊');
        }
        if (key === 'elDefAll') return '九元素抗性';
        if (key === 'elAtkAll') return '全元素攻擊';
        return String(key);
    }

    function isPct(key) {
        var s = STATS[key];
        if (s) return !!s.pct;
        if (/^elDef_/.test(key) || /^elAtk_/.test(key)) return true;
        if (key === 'elDefAll' || key === 'elAtkAll') return true;
        if (/Pct$/.test(key) || /Rate$/.test(key) || /Chance$/.test(key)) return true;
        var idx = codexNameIndex();
        var C = window.HY && window.HY.Data && window.HY.Data.STAT_CODEX;
        if (C && C.groups && idx[key]) {
            for (var gi = 0; gi < C.groups.length; gi++) {
                var stats = C.groups[gi].stats || [];
                for (var si = 0; si < stats.length; si++) {
                    if (stats[si].key === key && stats[si].unit === '%') return true;
                }
            }
        }
        return false;
    }
    function capOf(key) {
        var s = STATS[key];
        return (s && typeof s.cap === 'number') ? s.cap : null;
    }
    /** 將屬性值格式化成顯示文字 */
    function formatStat(key, val) {
        var s = STATS[key];
        var v = Number(val) || 0;
        if (!s) return String(v);
        var sign = v >= 0 ? '+' : '';
        if (s.pct) return sign + (Math.round(v * 10) / 10) + '%';
        return sign + Math.floor(v);
    }
    /** 依分組列出屬性 */
    function statsByGroup(group) {
        return STAT_KEYS.filter(function (k) { return STATS[k].group === group; });
    }

    window.HY.StatRegistry = {
        STATS: STATS,
        STAT_KEYS: STAT_KEYS,
        GROUP_NAMES: GROUP_NAMES,
        statInfo: statInfo,
        statName: statName,
        isPct: isPct,
        capOf: capOf,
        formatStat: formatStat,
        statsByGroup: statsByGroup,
        count: STAT_KEYS.length
    };

    if (window.console && window.console.log) {
        console.log('[statRegistry] ✓ 已載入 ' + STAT_KEYS.length + ' 個屬性定義');
    }
})();

