    'use strict';
    var Data = window.HY.Data;

    /* 靈獸系統已移除：保留空表供舊程式讀取不報錯 */
    if (!Data.PETS) Data.PETS = {};
    if (!Data.PET_IDS) Data.PET_IDS = [];

    /* ══════════════════════════════════════════════════════
       一、常數
       ══════════════════════════════════════════════════════ */
