        /* 魂力 → 屬性：1 年 = 0.001 點全屬性 */
        POWER_PER_YEAR: 0.001,
        /* 魂力上限（年）百萬年 */
        MAX_YEARS: 1000000,
        /* ⭐ v588：武魂掉落時的魂力範圍（年）
           ──────────────────────────────────────────────────
           使用者要求「掉落隨機 魂力 1~100」。
           不論 BOSS 等級一律隨機 1~100 年，靠餵食堆疊成長。 */
        DROP_YEARS_MIN: 1,
        DROP_YEARS_MAX: 100,
        /* ⭐ v588：掉落時成長值固定為 0（只能靠融合提升） */
        DROP_GROWTH_START: 0,
        /* 融合：成長值隨機增量 */
        GROWTH_MIN: 0.1,
        GROWTH_MAX: 0.3,
        /* 成長值上限（融合累加，使用者指定上限 5） */
        GROWTH_CAP: 5,
        /* 成長值對屬性的倍率：最終 = 魂力換算 × (1 + 成長值 × 係數)；滿成長 5 → 最高 ×1.5 */
        GROWTH_ATTR_RATE: 0.1,
        GROWTH_MULTIPLIER: true,
        /* 附身：武魂五圍（力敏體氣神）依比例疊到角色，再走角色五圍→戰鬥公式 */
        EQUIP_ATTR_RATE: 0.5,
