    /* ⭐ v610：舊存檔遷移 —— 舊版 95 隻（wh_01 ~ wh_95）已整批下架，
       改用山海經異獸。舊實例的 defId 已不存在，
       這裡依「持有順序」重新對應到新武魂，並保留魂力與成長值，
       避免玩家倉庫出現空白或無法顯示的武魂。
       對應規則：用舊 defId 的序號 → 新表的同序號（循環），
       同時記錄 legacyId 供必要時回溯。 */
    Data.LEGACY_MIGRATE = (function () {
        var map = {};
        var n = Data.WUHUNS.length;
        /* 只建 wh_01 ~ wh_95（舊表規模），避免序號補零回繞造成 key 覆蓋 */
        for (var i = 1; i <= 95; i++) {
            var key = 'wh_' + (i < 10 ? '0' + i : '' + i);
            map[key] = Data.WUHUNS[(i - 1) % n].id;
        }
        return map;
    })();

    /** 把舊武魂實例（wh_XX）換成新武魂定義，回傳是否變更 */
    Data.migrateLegacyWuhun = function (inst) {
        if (!inst) return false;
        var id = String(inst.defId || inst.id || '');
        if (!/^wh_\d+$/.test(id)) return false;
        var nid = Data.LEGACY_MIGRATE[id];
        if (!nid) {
            /* 超出範圍（wh_96 以上）→ 循環對應 */
            var n = Data.WUHUNS.length;
            var idx = Math.max(0, (parseInt(id.replace('wh_', ''), 10) - 1) % n);
            nid = Data.WUHUNS[idx].id;
        }
        var def = Data.WUHUN_BY_ID[nid];
        if (!def) return false;
        inst.legacyId = inst.legacyId || id;
        inst.defId = def.id;
        inst.name = def.name;
        inst.icon = def.icon;
        inst.art = def.art || '';
        inst.element = def.element;
        inst.trait = def.trait;
        inst.skill = def.skill;
        inst.skillType = def.skillType;
        return true;
    };

