    /** 補上檔案路徑（避免每筆手寫重複） */
    function attachArt(list) {
        list.forEach(function (p) {
            p.full = DIR + p.id + '_full.jpg';
            p.avatar = DIR + p.id + '_avatar.jpg';
        });
        return list;
    }
    /* 21–50 沒有對應圖檔，放進選擇器只會 404。先保留有圖的 01–20。 */
    BOYS.length = 20;
    GIRLS.length = 20;
    attachArt(BOYS);
    attachArt(GIRLS);

    var ALL = BOYS.concat(GIRLS);
    var BY_ID = {};
    ALL.forEach(function (p) { BY_ID[p.id] = p; });

    var Data = (HY.Data = HY.Data || {});
    Data.CHARACTER_ART = ALL;
    Data.CHARACTER_ART_BOYS = BOYS;
    Data.CHARACTER_ART_GIRLS = GIRLS;
    Data.CHARACTER_ART_BY_ID = BY_ID;

