// js/delveData.js  (v1)
// PoE1 礦坑（Delve）資料表：生物群系、節點類型、難度曲線、化石掉寶表
//
// 設計重點：
//   ⭐ 無限深度（endless），越深敵人越強、化石越好
//   ⭐ 敵人不是憑公式硬算，而是「從既有 Data.MAPS 取樣後對數插值」
//      因為本作難度跨度極大（Lv.1 的 70 HP → Lv.300 的 6800 萬 HP），
//      而且是逐段變化的成長率，純公式會嚴重走鐘。
window.HY = window.HY || {};
window.HY.Data = window.HY.Data || {};
(function () {
    const Data = window.HY.Data;
    // ═══════════════════════════════════════════════════════════════
    //  1. 礦坑設定
    // ═══════════════════════════════════════════════════════════════
    Data.DELVE_CONFIG = {
        START_DEPTH: 1,
        /* 每層基礎等級。深度 1 → Lv.10 起跳，之後線性成長 */
        BASE_LEVEL: 10,
        LEVEL_PER_DEPTH: 2.4,
        /* 深度上限（實際不設上限，此值只用於 UI 進度條比例） */
        LEVEL_CAP: 300,
        /* 每層可選節點數 */
        NODES_PER_DEPTH: 3,
        /* ⭐ 硫磺消耗：越深越貴。基礎 1，每 DIG 層 +1（無上限）
           ⭐ v60：使用者要求「硫磺消耗 ×10」
              原本基礎 1 / 每 5 層 +1 → 改為基礎 10 / 每 5 層 +10
              起始硫磺同步 ×10（25 → 250），避免一開始就卡住。 */
        FUEL_BASE_COST: 10,
        FUEL_COST_EVERY_DEPTHS: 5,
        /* ⭐ 取消硫磺上限（改為 0 = 不限制） */
        MAX_FUEL: 0,
        /* 起始硫磺
           ⭐ v60：因為消耗 ×10，起始值同步 ×10（25 → 250）
              250 足以探索約 10~12 步（含分支），之後靠打怪或硫磺礦脈補給。 */
        START_FUEL: 250,
        /* 擊敗怪物節點回復硫磺（基礎值，會隨深度提高）
           ⭐ v60：同步 ×10，否則玩家永遠補不回來 */
        FUEL_PER_MONSTER: 10,
        FUEL_PER_MONSTER_PER_5_DEPTH: 10,
        /* 每層通關經驗/金幣倍率（相對同級一般怪） */
        EXP_MULT: 1.5,
        GOLD_MULT: 1.2,
        /* 稀有度加成：每 5 層，怪物詞綴觸發率 +4%（上限 +40%） */
        AFFIX_PER_5_DEPTH: 4,
        AFFIX_BONUS_CAP: 40,
        /* 敗北時保留已取得化石的機率（0 = 全保留，1 = 全丟失） */
        DEATH_LOSS_PCT: 0
    };
    /* ⭐ 與作弊面板連動：若 HY.GameConfig.delve 有值，以它為準。
       原本這些常數寫死在這裡，作弊面板改了也不會生效（顯示「未接線」）。
       現在改成讀取時即時合併，改完下次計算就生效。 */
    (function applyConfig() {
        var GC = window.HY && window.HY.GameConfig;
        var dc = GC && GC.delve;
        if (!dc) return;
        Object.keys(dc).forEach(function (k) {
            if (Data.DELVE_CONFIG[k] !== undefined &&
                typeof dc[k] === 'number' && isFinite(dc[k])) {
                Data.DELVE_CONFIG[k] = dc[k];
            }
        });
    })();
    /* ⭐ 指定深度的硫磺消耗（無上限，越深越貴） */
    Data.delveFuelCostAt = function (depth) {
        var C = Data.DELVE_CONFIG;
        var d = Math.max(1, Math.floor(depth || 1));
        var extra = Math.floor((d - 1) / Math.max(1, C.FUEL_COST_EVERY_DEPTHS));
        return C.FUEL_BASE_COST + extra;
    };
    /* ⭐ 指定深度擊敗怪物可回復的硫磺
       ⚠️ v2：因為「每一步移動都要硫磺」，而一層的完整推進是
              「進入節點（-C）」＋「深入下一層（-C）」＝ 2C。
              若打怪只回 C，玩家會越打越窮 → 一定卡死。
              所以回復量改為「2 × 當前每步成本」，打怪趕路才可持續；
              只探索分支（不深入）時仍是淨虧，保留風險取捨。 */
    Data.delveFuelGainAt = function (depth, isBoss) {
        var C = Data.DELVE_CONFIG;
        var d = Math.max(1, Math.floor(depth || 1));
        var step = Data.delveFuelCostAt(d);
        var gain = step * 2;
        if (isBoss) gain += 2 + Math.floor(d / 10);
        return Math.max(1, Math.round(gain));
    };
    // ═══════════════════════════════════════════════════════════════
    //  2. 生物群系（每 4 層循環一次，深度決定可掉化石池）
    // ═══════════════════════════════════════════════════════════════
    Data.DELVE_BIOMES = [
        {
            id: 'fungal', name: '菌菇洞窟', color: '#4ade80', icon: '🍄',
            desc: '潮濕陰暗的地底菌毯，孢子飄散。',
            fossilPool: ['fossil_dense', 'fossil_lucent', 'fossil_aberrant', 'fossil_bloodstained'],
            enemyNames: ['菌孢爬行者', '腐蝕菇人', '孢子噴吐者', '菌絲巨蛛']
        },
        {
            id: 'frozen', name: '冰封地層', color: '#67e8f9', icon: '❄️',
            desc: '永不融化的遠古冰層，寒氣刺骨。',
            fossilPool: ['fossil_frigid', 'fossil_prismatic', 'fossil_aetheric', 'fossil_sanctified'],
            enemyNames: ['冰晶守衛', '霜噬亡骸', '極寒巨像', '凍土潛伏者']
        },
        {
            id: 'magma', name: '熔岩深窟', color: '#f97316', icon: '🔥',
            desc: '岩漿翻湧的地心裂縫，熱浪扭曲空氣。',
            fossilPool: ['fossil_scorched', 'fossil_jagged', 'fossil_metallic', 'fossil_faceted'],
            enemyNames: ['熔岩元素', '焰息魔犬', '熔鐵傀儡', '灰燼祭司']
        },
        {
            id: 'abyssal', name: '深淵遺跡', color: '#a855f7', icon: '🕳️',
            desc: '上古文明沉入地底的殘骸，迴盪著低語。',
            fossilPool: ['fossil_bound', 'fossil_glyphic', 'fossil_enchanted', 'fossil_tangled'],
            enemyNames: ['深淵祭司', '虛空行者', '遺跡守墓人', '低語之影']
        },
        {
            id: 'petrified', name: '石化森林', color: '#94a3b8', icon: '🌲',
            desc: '遠古巨木化為磐石，枝椏刺穿岩頂。',
            fossilPool: ['fossil_serrated', 'fossil_shuddering', 'fossil_corroded', 'fossil_gilded'],
            enemyNames: ['石化樹人', '荊棘潛伏者', '岩皮巨熊', '枯枝獵手']
        },
        {
            id: 'crystalline', name: '水晶迷宮', color: '#c084fc', icon: '💎',
            desc: '折射萬千倒影的水晶廊道，令人迷失方向。',
            fossilPool: ['fossil_faceted', 'fossil_prismatic', 'fossil_perfect', 'fossil_fractured'],
            enemyNames: ['水晶哨兵', '稜鏡幻影', '琉璃巨像', '折射之眼']
        }
    ];
    Data.delveBiomeAt = function (depth) {
        var n = (typeof depth === 'number' && depth > 0) ? Math.floor(depth) : 1;
        return Data.DELVE_BIOMES[(n - 1) % Data.DELVE_BIOMES.length];
    };
    // ═══════════════════════════════════════════════════════════════
    //  3. 節點類型
    // ═══════════════════════════════════════════════════════════════
    Data.DELVE_NODE_TYPES = {
        monster: {
            id: 'monster', name: '怪物巢穴', icon: '⚔️', color: '#f87171',
            desc: '擊敗巢穴守衛，獲得經驗與少量化石。',
            needBattle: true
        },
        treasure: {
            id: 'treasure', name: '埋藏寶箱', icon: '🎁', color: '#fbbf24',
            desc: '直接開啟，獲得裝備或通貨。',
            needBattle: false
        },
        fossil: {
            id: 'fossil', name: '化石礦脈', icon: '🪨', color: '#c084fc',
            desc: '開採礦脈，必定獲得 1~3 顆化石。',
            needBattle: false
        },
        gem: {
            id: 'gem', name: '寶石礦脈', icon: '💎', color: '#38bdf8',
            desc: '開採晶簇，必定獲得 1~2 顆珠寶（可鑲嵌於天賦樹）。',
            needBattle: false
        },
        fuel: {
            id: 'fuel', name: '硫磺礦泉', icon: '⛽', color: '#38bdf8',
            desc: '補充推進所需的硫磺。',
            needBattle: false
        },
        boss: {
            id: 'boss', name: '地層霸主', icon: '👹', color: '#dc2626',
            desc: '強大的地層守護者，獎勵豐厚但極其危險。',
            needBattle: true, isBoss: true
        }
    };
    /* 每層 3 個節點的類型分佈（依深度調整 boss 出現頻率） */
    Data.delveNodeTypeRoll = function (depth) {
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        var bossChance = (d % 10 === 0) ? 100 : Math.min(18, 4 + d * 0.35);
        var roll = Math.random() * 100;
        if (roll < bossChance) return 'boss';
        if (roll < bossChance + 30) return 'monster';
        if (roll < bossChance + 48) return 'fossil';
        if (roll < bossChance + 62) return 'gem';        /* ⭐ 珠寶來源 */
        if (roll < bossChance + 77) return 'treasure';
        return 'fuel';
    };
    // ═══════════════════════════════════════════════════════════════
    //  4. 難度曲線
    // ═══════════════════════════════════════════════════════════════
    Data.delveLevelAt = function (depth) {
        var C = Data.DELVE_CONFIG;
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        var lv = C.BASE_LEVEL + (d - 1) * C.LEVEL_PER_DEPTH;
        return Math.max(1, Math.round(lv));
    };
    /* 深度 → 該層怪物的詞綴觸發率加成（百分比） */
    Data.delveAffixBonusAt = function (depth) {
        var C = Data.DELVE_CONFIG;
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        return Math.min(C.AFFIX_BONUS_CAP, Math.floor(d / 5) * C.AFFIX_PER_5_DEPTH);
    };
    // ═══════════════════════════════════════════════════════════════
    //  5. 敵人取樣池（從既有地圖表建立，供對數插值）
    // ═══════════════════════════════════════════════════════════════
    var _pool = null;
    function buildPool() {
        if (_pool) return _pool;
        var maps = Data.MAPS || {};
        var list = [];
        Object.keys(maps).forEach(function (mid) {
            var m = maps[mid];
            if (!m || !Array.isArray(m.enemies)) return;
            m.enemies.forEach(function (e) {
                if (!e || typeof e.lv !== 'number' || !(e.hp > 0)) return;
                /* 排除「最終魔王級」以外的頭目並不必要，全部納入取樣，
                   因為插值只取相鄰兩點，不會被極值帶歪。 */
                list.push({
                    lv: e.lv, hp: e.hp, atk: e.atk || 1, def: e.def || 0,
                    hit: e.hit || 90, eva: e.eva || 0, crit: e.crit || 0,
                    critRes: e.critRes || 0, exp: e.exp || 1, sp: e.sp || 1,
                    gold: e.gold || 1, faction: e.faction || '', mapId: mid
                });
            });
        });
        list.sort(function (a, b) { return a.lv - b.lv; });
        _pool = list;
        return _pool;
    }
    /* 對數插值：指數型成長曲線在 log 空間是線性的 */
    function lerpLog(a, b, t) {
        var va = (a > 0) ? Math.log(a) : 0;
        var vb = (b > 0) ? Math.log(b) : 0;
        return Math.exp(va + (vb - va) * t);
    }
    function lerpLin(a, b, t) {
        return a + (b - a) * t;
    }
    /**
     * 取得指定等級的礦坑敵人基準數值。
     * 超越取樣池最高等級時，用最後一段的成長率外推。
     */
    Data.delveEnemyBaseAt = function (lv) {
        var pool = buildPool();
        if (!pool.length) {
            /* 沒有地圖資料時的保險值 */
            var k0 = Math.max(1, lv);
            return { lv: k0, hp: 100 * k0, atk: 15 * k0, def: 5 * k0, hit: 90 + k0,
                     eva: k0, crit: 5, critRes: 0, exp: 40 * k0, sp: 30 * k0, gold: 30 * k0 };
        }
        var target = Math.max(1, lv);
        var first = pool[0], last = pool[pool.length - 1];
        /* 低於最低取樣點 → 等比縮小 */
        if (target <= first.lv) {
            var s0 = target / Math.max(1, first.lv);
            return {
                lv: target,
                hp: Math.max(1, Math.round(first.hp * s0)),
                atk: Math.max(1, Math.round(first.atk * s0)),
                def: Math.round(first.def * s0),
                hit: first.hit, eva: Math.round(first.eva * s0),
                crit: first.crit, critRes: first.critRes,
                exp: Math.max(1, Math.round(first.exp * s0)),
                sp: Math.max(1, Math.round(first.sp * s0)),
                gold: Math.max(1, Math.round(first.gold * s0))
            };
        }
        /* 高於最高取樣點 → 沿用最後一段成長率外推 */
        if (target > last.lv) {
            var prev = pool[pool.length - 2] || first;
            var span = Math.max(1, last.lv - prev.lv);
            var ratePerLv = Math.pow(last.hp / Math.max(1, prev.hp), 1 / span);
            var extra = target - last.lv;
            var mult = Math.pow(ratePerLv, extra);
            /* 外推時略為收斂，避免深度 1000 出現天文數字 */
            mult = Math.pow(mult, 0.92);
            return {
                lv: target,
                hp: Math.round(last.hp * mult),
                atk: Math.round(last.atk * mult),
                def: Math.round(last.def * mult),
                hit: Math.round(last.hit + extra * 0.15),
                eva: Math.round(last.eva * Math.pow(mult, 0.5)),
                crit: Math.min(95, Math.round(last.crit + extra * 0.05)),
                critRes: Math.min(200, Math.round(last.critRes + extra * 0.08)),
                exp: Math.round(last.exp * mult),
                sp: Math.round(last.sp * mult),
                gold: Math.round(last.gold * mult)
            };
        }
        /* 正常區間：找到相鄰兩點後插值 */
        var lo = 0, hi = pool.length - 1;
        for (var i = 0; i < pool.length - 1; i++) {
            if (pool[i].lv <= target && pool[i + 1].lv >= target) { lo = i; hi = i + 1; break; }
        }
        var a = pool[lo], b = pool[hi];
        var t = (b.lv === a.lv) ? 0 : (target - a.lv) / (b.lv - a.lv);
        return {
            lv: target,
            hp: Math.round(lerpLog(a.hp, b.hp, t)),
            atk: Math.round(lerpLog(a.atk, b.atk, t)),
            def: Math.round(lerpLog(Math.max(1, a.def), Math.max(1, b.def), t)),
            hit: Math.round(lerpLin(a.hit, b.hit, t)),
            eva: Math.round(lerpLin(a.eva, b.eva, t)),
            crit: Math.round(lerpLin(a.crit, b.crit, t)),
            critRes: Math.round(lerpLin(a.critRes, b.critRes, t)),
            exp: Math.round(lerpLog(a.exp, b.exp, t)),
            sp: Math.round(lerpLog(a.sp, b.sp, t)),
            gold: Math.round(lerpLog(a.gold, b.gold, t))
        };
    };
    // ═══════════════════════════════════════════════════════════════
    //  6. 掉寶
    // ═══════════════════════════════════════════════════════════════
    /* 化石礦脈：依深度決定能開採到的化石等級 */
    Data.delveFossilPool = function (depth) {
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        var biome = Data.delveBiomeAt(d);
        var pool = (biome.fossilPool || []).slice();
        /* 深度 30 以上才可能出現完美化石 */
        if (d < 30 && Data.FOSSILS) {
            pool = pool.filter(function (id) {
                var f = Data.FOSSILS[id];
                return !f || f.tier !== 'mythic';
            });
        }
        if (!pool.length) pool = Data.FOSSIL_ORDER ? Data.FOSSIL_ORDER.slice(0, 6) : [];
        return pool;
    };
    /* 怪物節點的化石掉落機率（百分比） */
    Data.delveMonsterFossilChance = function (depth) {
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        return Math.min(70, 8 + d * 0.8);
    };
    /* 怪物節點可掉幾顆 */
    Data.delveFossilCountRoll = function (depth, isBoss) {
        var d = (typeof depth === 'number' && depth > 0) ? depth : 1;
        if (isBoss) return 2 + Math.floor(Math.random() * 3);          /* 2~4 */
        var cap = Math.min(3, 1 + Math.floor(d / 12));
        return 1 + Math.floor(Math.random() * cap);
    };
    if (window.console && window.console.log) {
        console.log('[HY Delve] 已載入 ' + Data.DELVE_BIOMES.length + ' 個生物群系');
    }
})();
