  /* ═══ 展開成節點物件（與原 talentData 相同結構）═══ */
  var NODES = {};
  var ORDER = [];
  for (var i = 0; i < RAW_NODES.length; i++) {
    var r = RAW_NODES[i];
    var id = String(r[0]);
    var outIds = r[6] ? String(r[6]).split(",").filter(function (v) { return v; }) : [];
    NODES[id] = {
      id: id,
      name: r[1],
      icon: r[2],
      x: r[3],
      y: r[4],
      isNotable: r[5] === 1,
      isKeystone: r[5] === 2,
      isJewelSocket: r[5] === 3,
      isClassStart: r[5] === 4,
      out: outIds,
      /** POE 原始效果文字（英文），由 talentStatZh.js 翻成中文 */
      stats: r[7] || [],
      bonus: { attr: {}, flat: {}, more: {}, extra: {} },
      group: r[8] || 0,
      orbit: (typeof r[9] === "number") ? r[9] : -1,
      /** 節點在軌道上的角度（度，從正上方起算順時針）。-1 = 無軌道 */
      angle: (typeof r[10] === "number") ? r[10] : -1
    };
    ORDER.push(id);
  }

  /* ═══ 補上 in 反向索引（POE 原始資料只有 out）═══ */
  Object.keys(NODES).forEach(function (id) {
    var n = NODES[id];
    (n.out || []).forEach(function (o) {
      var t = NODES[String(o)];
      if (!t) return;
      if (!t.in) t.in = [];
      t.in.push(id);
    });
  });

