// js/ascendancyZhNames.js  (v1)
// ⭐ 職業昇華：只改「名稱」為仙俠風，完全不動節點內容
//
// ══════════════════════════════════════════════════════════════
// 【需求】
//   使用者原話：「我只是要改變名稱仙俠而已」
//
//   也就是說：
//     · 昇華天賦的 21 條分支、每個節點的數值與連線 —— 全部保留原樣
//     · 只把「職業名稱」與「分支名稱」的英文改成仙俠中文
//
// 【做法】
//   1. 不改 ascendancyData.js（那是 456 行的官方資料，改了就回不去）
//   2. 本檔在載入後，就地改寫：
//        Data.ASCENDANCY_CLASSES[classId][i].name
//        Data.ASCENDANCY_GEO 不變（分支 id 不變）
//        Data.ASCENDANCY_NODES 不變（節點內容不變）
//   3. 節點名稱本身由 ascendancyZh.js 負責翻譯（已存在），不動
//
//   ⚠️ 只改 name 欄位，不改 id —— 因為：
//        SECT_CLASS（門派 → 職業）的 46 筆對照、
//        ASCENDANCY_BY_BRANCH（分支 → 節點）的 key
//        全部依賴 id。改 id 會讓所有存檔的昇華配置失效。
// ══════════════════════════════════════════════════════════
window.HY = window.HY || {};
(function (HY) {
    'use strict';

    function D() { return window.HY.Data || {}; }

    /* ══════════════════════════════════════════════════════
       一、職業名稱（7 個）
       ──────────────────────────────────────────────────────────
       保留 POE 職業 id，只換顯示名為仙俠風。
       ══════════════════════════════════════════════════════ */
    var CLASS_NAMES = {
        Scion:    { name: '俠客', icon: '🎖️', color: '#f0c674',
                    desc: '名門之後，博採眾長。' },
        Marauder: { name: '力士', icon: '💪', color: '#ef4444',
                    desc: '外功剛猛，以力破巧。' },
        Ranger:   { name: '遊俠', icon: '🏹', color: '#4ade80',
                    desc: '身法矯健，來去如風。' },
        Witch:    { name: '術士', icon: '🔮', color: '#a855f7',
                    desc: '內功深厚，擅咒法與召喚。' },
        Duelist:  { name: '劍客', icon: '⚔️', color: '#38bdf8',
                    desc: '兵刃為命，劍術為魂。' },
        Templar:  { name: '護法', icon: '🛡️', color: '#fbbf24',
                    desc: '佛道護體，金剛不壞。' },
        Shadow:   { name: '刺客', icon: '🗡️', color: '#818cf8',
                    desc: '暗夜行者，毒計與機關。' }
    };

    /* ══════════════════════════════════════════════════════
       二、分支名稱（21 條）
       ──────────────────────────────────────────────────────────
       key 是原本的 POE 分支 id，只換 name 為仙俠名。
       ══════════════════════════════════════════════════════ */
    var BRANCH_NAMES = {
        /* ── Scion 俠客 ── */
        Ascendant:   { name: '天驕',   icon: '🎖️', color: '#f0c674' },
        Reliquarian: { name: '藏珍',   icon: '🏺', color: '#fbbf24' },
        Luminary:    { name: '明燭',   icon: '🕯️', color: '#fcd34d' },

        /* ── Marauder 力士 ── */
        Juggernaut:  { name: '鐵壁',   icon: '🛡️', color: '#6ee7b7' },
        Berserker:   { name: '狂戰',   icon: '💥', color: '#ef4444' },
        Chieftain:   { name: '蠻酋',   icon: '🔥', color: '#f97316' },

        /* ── Ranger 遊俠 ── */
        Raider:      { name: '疾風',   icon: '💨', color: '#4ade80' },
        Deadeye:     { name: '獵影',   icon: '🎯', color: '#38bdf8' },
        Pathfinder:  { name: '尋蹤',   icon: '🧭', color: '#34d399' },

        /* ── Witch 術士 ── */
        Occultist:   { name: '玄陰',   icon: '🌑', color: '#a855f7' },
        Elementalist:{ name: '五行',   icon: '🌀', color: '#f97316' },
        Necromancer: { name: '御魂',   icon: '💀', color: '#818cf8' },

        /* ── Duelist 劍客 ── */
        Slayer:      { name: '斬龍',   icon: '🗡️', color: '#f0c674' },
        Gladiator:   { name: '刀客',   icon: '⚔️', color: '#fbbf24' },
        Champion:    { name: '戰神',   icon: '🏆', color: '#f43f5e' },

        /* ── Templar 護法 ── */
        Inquisitor:  { name: '業火',   icon: '🔥', color: '#f97316' },
        Hierophant:  { name: '陣師',   icon: '🔯', color: '#c084fc' },
        Guardian:    { name: '金剛',   icon: '🛡️', color: '#fbbf24' },

        /* ── Shadow 刺客 ── */
        Assassin:    { name: '暗殺',   icon: '🗡️', color: '#818cf8' },
        Trickster:   { name: '幻影',   icon: '👤', color: '#a78bfa' },
        Saboteur:    { name: '機關',   icon: '⚙️', color: '#a3e635' }
    };

    /* ══════════════════════════════════════════════════════
       三、套用
       ══════════════════════════════════════════════════════ */
    var _done = false, _stat = { classes: 0, branches: 0 };

    function apply() {
        if (_done) return _stat;
        var Data = D();
        if (!Data.ASCENDANCY_CLASSES) return _stat;

        /* ① 職業 → 分支清單：只改 name，id 不動 */
        Object.keys(Data.ASCENDANCY_CLASSES).forEach(function (classId) {
            var list = Data.ASCENDANCY_CLASSES[classId];
            if (!Array.isArray(list)) return;
            list.forEach(function (b) {
                var bn = BRANCH_NAMES[b.id];
                if (bn) {
                    if (!b.__poeName) b.__poeName = b.name;
                    b.name = bn.name;
                    b.icon = bn.icon;
                    b.color = bn.color;
                    _stat.branches++;
                }
            });
            _stat.classes++;
        });

        _done = true;
        console.log('[HY AscZhNames] ✓ 已中文化 ' + _stat.classes + ' 個職業 / ' +
            _stat.branches + ' 條升華分支（節點內容完全不變）');
        return _stat;
    }

    /* 分支名查詢（給 UI 用） */
    function branchName(branchId) {
        var bn = BRANCH_NAMES[branchId];
        return bn ? bn.name : branchId;
    }
    /* 職業名查詢 */
    function className(classId) {
        var cn = CLASS_NAMES[classId];
        return cn ? cn.name : classId;
    }
    function classInfo(classId) {
        return CLASS_NAMES[classId] || null;
    }
    function branchInfo(branchId) {
        return BRANCH_NAMES[branchId] || null;
    }

    window.HY.AscendancyZhNames = {
        apply: apply,
        branchName: branchName,
        className: className,
        classInfo: classInfo,
        branchInfo: branchInfo,
        CLASS_NAMES: CLASS_NAMES,
        BRANCH_NAMES: BRANCH_NAMES
    };

    /* 輪詢等待資料載入（bootLoader 非同步） */
    var tries = 0;
    var timer = setInterval(function () {
        tries++;
        var ok = false;
        try {
            var Data = D();
            if (Data.ASCENDANCY_CLASSES &&
                Object.keys(Data.ASCENDANCY_CLASSES).length >= 7) {
                apply();
                ok = _done;
            }
        } catch (e) { }
        if (ok || tries > 90) clearInterval(timer);
    }, 200);

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(function () { try { apply(); } catch (e) { } }, 150);
    }
})(window.HY);

