// js/talentIconMap.js
// 🎨 POE 天賦圖示 → 本作圖示 對照層
//
// 背景：
//   talentDataPoe.js 保留了 POE 官方的圖示路徑，例如
//     "Art/2DArt/SkillIcons/passives/plusstrength.png"
//     "Art/2DArt/SkillIcons/passives/colddamage.png"
//   POE 官方 CDN 已改版，舊路徑全部 404，無法直接抓圖。
//
// 解法：
//   本作 assets/talent-icons 已有 77 個通用圓形徽章（青銅齒輪外框）。
//   這裡用「關鍵字權重比對」把 POE 的 1087 種圖示名對應到那 77 個：
//     ① 先看圖示檔名的關鍵字（fire / cold / life / crit / shield …）
//     ② 再看節點的效果文字（stats）輔助判斷
//     ③ 都無命中時，依節點類型給預設值
//
//   這樣每個節點都能顯示一個「看起來合理」的圖示，
//   而不是全部畫成幾何色塊。
//
// 對外 API：
//   HY.TalentIcon.map(poeIconPath, node) → 本作圖示檔名（icon_XX.png）
window.HY = window.HY || {};
(function () {
    'use strict';

    /* ══════════════════════════════════════════════════════════
       本作 77 個圖示的語意對照
       （由 assets/talent-icons 既有圖示的實際內容歸納）
       ══════════════════════════════════════════════════════════ */
    var ICONS = {
        attrStr:  'icon_00.png',   // 力道
        attrDex:  'icon_01.png',   // 身法
        attrInt:  'icon_02.png',   // 內息
        attrCon:  'icon_03.png',   // 體魄
        sword:    'icon_04.png',   // 劍
        axe:      'icon_05.png',   // 斧
        mace:     'icon_06.png',   // 錘
        bow:      'icon_07.png',   // 弓
        wand:     'icon_08.png',   // 杖
        dagger:   'icon_09.png',   // 匕
        claw:     'icon_10.png',   // 爪
        palm:     'icon_11.png',   // 掌
        staff:    'icon_12.png',   // 長棍
        socket:   'icon_13.png',   // 寶石插槽
        shield:   'icon_14.png',   // 盾
        armor:    'icon_15.png',   // 甲
        helm:     'icon_16.png',   // 盔
        boot:     'icon_17.png',   // 靴
        glove:    'icon_18.png',   // 手套
        belt:     'icon_19.png',   // 腰帶
        ring:     'icon_20.png',   // 戒
        amulet:   'icon_21.png',   // 項鍊
        life:     'icon_22.png',   // 生命
        mana:     'icon_23.png',   // 魔力
        es:       'icon_24.png',   // 護盾
        fire:     'icon_25.png',   // 火
        cold:     'icon_26.png',   // 冰
        lightning:'icon_27.png',   // 雷
        chaos:    'icon_28.png',   // 混沌
        phys:     'icon_29.png',   // 物理
        crit:     'icon_30.png',   // 爆擊
        speed:    'icon_31.png',   // 速度
        aoe:      'icon_32.png',   // 範圍
        cluster:  'icon_33.png',   // 群
        proj:     'icon_34.png',   // 投射
        dot:      'icon_35.png',   // 持續
        leech:    'icon_36.png',   // 偷取
        regen:    'icon_37.png',   // 回復
        block:    'icon_38.png',   // 格擋
        dodge:    'icon_39.png',   // 閃避
        accuracy: 'icon_40.png',   // 命中
        keystone: 'icon_41.png',   // 星（關鍵天賦）
        minion:   'icon_42.png',   // 召喚
        totem:    'icon_43.png',   // 圖騰
        curse:    'icon_44.png',   // 詛咒
        aura:     'icon_45.png',   // 光環
        flask:    'icon_46.png',   // 藥劑
        trap:     'icon_47.png',   // 陷阱
        mine:     'icon_48.png',   // 地雷
        warcry:   'icon_49.png',   // 戰吼
        stance:   'icon_50.png',   // 姿態
        charge:   'icon_51.png',   // 充能
        rage:     'icon_52.png',   // 怒氣
        fortify:  'icon_53.png',   // 強化
        stun:     'icon_54.png',   // 眩暈
        bleed:    'icon_55.png',   // 流血
        poison:   'icon_56.png',   // 中毒
        ignite:   'icon_57.png',   // 點燃
        freeze:   'icon_58.png',   // 冰凍
        shock:    'icon_59.png',   // 感電
        spell:    'icon_60.png',   // 法術
        attack:   'icon_61.png',   // 攻擊
        melee:    'icon_62.png',   // 近戰
        twohand:  'icon_63.png',   // 雙手
        dual:     'icon_64.png',   // 雙持
        movement: 'icon_65.png',   // 移動
        duration: 'icon_66.png',   // 持續時間
        cooldown: 'icon_67.png',   // 冷卻
        rarity:   'icon_68.png',   // 掉落稀有度
        quantity: 'icon_69.png',   // 掉落數量
        light:    'icon_70.png',   // 視野
        keystone2:'icon_71.png',   // 關鍵天賦（備用）
        notable:  'icon_72.png',   // 顯著天賦
        hub:      'icon_73.png',   // 樞紐
        energy:   'icon_74.png',   // 能量
        defense:  'icon_75.png',   // 防禦
        generic:  'icon_76.png'    // 通用
    };

    /* ══════════════════════════════════════════════════════════
       關鍵字 → 圖示（依優先序，越前面越優先）
       比對對象：POE 圖示檔名（小寫） + 節點效果文字（小寫）
       ══════════════════════════════════════════════════════════ */
    var RULES = [
        /* 屬性 */
        [/\bplusstrength\b|strength/,            ICONS.attrStr],
        [/\bplusdexterity\b|dexterity/,          ICONS.attrDex],
        [/\bplusintelligence\b|intelligence/,    ICONS.attrInt],
        [/allattributes|attributes/,              ICONS.attrCon],

        /* 元素 */
        [/fire|ignite|burning/,                   ICONS.fire],
        [/cold|freeze|chill|frost/,               ICONS.cold],
        [/lightning|shock|thunder/,               ICONS.lightning],
        [/chaos|poison|withered/,                 ICONS.chaos],
        [/elementaldamage|elemental/,             ICONS.fire],

        /* 傷害類型 */
        [/physical|2handeddamage|1handeddamage/,  ICONS.phys],
        [/damagespells|spelldamage|spell/,        ICONS.spell],
        [/melee/,                                 ICONS.melee],
        [/projectile|proj/,                       ICONS.proj],
        [/damageoverTime|dot|ailment/,            ICONS.dot],
        [/critical|crit/,                         ICONS.crit],
        [/attackdamage|attack/,                   ICONS.attack],

        /* 防禦 */
        [/energyshield/,                          ICONS.es],
        [/evasion|dodge/,                         ICONS.dodge],
        [/armour|armor|defence/,                  ICONS.armor],
        [/block|shield/,                          ICONS.block],
        [/accuracy/,                              ICONS.accuracy],
        [/stun/,                                  ICONS.stun],
        [/fortif/,                                ICONS.fortify],

        /* 資源 */
        [/life|health/,                           ICONS.life],
        [/mana/,                                  ICONS.mana],
        [/leech/,                                 ICONS.leech],
        [/regenerat|recovery|regen/,              ICONS.regen],
        [/\brage\b/,                              ICONS.rage],
        [/charge/,                                ICONS.charge],

        /* 速度與範圍（必須排在 proj 之前，否則 attackspeed 會被 projectile 攔截） */
        [/attackspeed|castspeed|weaponspeed/,     ICONS.speed],
        [/areaofeffect|aoe/,                      ICONS.aoe],
        [/projectile|proj/,                       ICONS.proj],
        [/movementspeed|movement/,                ICONS.movement],
        [/duration/,                              ICONS.duration],
        [/cooldown/,                              ICONS.cooldown],

        /* 機制 */
        [/minion|golem|summon/,                   ICONS.minion],
        [/totem/,                                 ICONS.totem],
        [/curse/,                                 ICONS.curse],
        [/aura/,                                  ICONS.aura],
        [/flask/,                                 ICONS.flask],
        [/trap/,                                  ICONS.trap],
        [/mine/,                                  ICONS.mine],
        [/warcry|cry/,                            ICONS.warcry],
        [/stance/,                                ICONS.stance],
        [/bleed/,                                 ICONS.bleed],
        [/freeze/,                                ICONS.freeze],
        [/shock/,                                 ICONS.shock],

        /* 掉落 */
        [/rarity/,                                ICONS.rarity],
        [/quantity/,                              ICONS.quantity],
        [/lightradius|light/,                     ICONS.light],

        /* 武器 */
        [/sword/,                                 ICONS.sword],
        [/\baxe/,                                 ICONS.axe],
        [/mace|sceptre/,                          ICONS.mace],
        [/\bbow/,                                 ICONS.bow],
        [/wand/,                                  ICONS.wand],
        [/dagger/,                                ICONS.dagger],
        [/claw/,                                  ICONS.claw],
        [/staff/,                                 ICONS.staff],
        [/dualwield|dual/,                        ICONS.dual]
    ];

    /** 依 POE 圖示路徑 + 節點資料挑選本作圖示 */
    function map(poeIconPath, node) {
        var icon = String(poeIconPath || '').toLowerCase();
        /* 只取檔名部分（去掉 Art/2DArt/SkillIcons/passives/ 前綴與 .png） */
        var base = icon.split('/').pop().replace(/\.png$/, '');

        var stats = (node && node.stats) ? node.stats.join(' ').toLowerCase() : '';
        var hay = base + ' ' + stats;

        /* ① 關鍵天賦優先給星形 */
        if (node && node.isKeystone) {
            return { file: ICONS.keystone, isSpecial: true };
        }
        /* ② 珠寶插槽給固定圖示 */
        if (node && node.isJewelSocket) {
            return { file: ICONS.socket, isSpecial: true };
        }
        /* ③ 空節點或精通空白節點用通用 */
        if (node && (!node.stats || !node.stats.length)) {
            return { file: ICONS.generic };
        }
        if (/masteryblank|masterygroup/.test(base)) {
            return { file: ICONS.generic };
        }

        /* ④ 關鍵字比對 */
        for (var i = 0; i < RULES.length; i++) {
            if (RULES[i][0].test(hay)) {
                return { file: RULES[i][1] };
            }
        }

        /* ⑤ 顯著天賦有專屬徽章 */
        if (node && node.isNotable) return { file: ICONS.notable };

        return { file: ICONS.generic };
    }

    window.HY.TalentIcon = {
        ICONS: ICONS,
        RULES: RULES,
        map: map
    };
})();

