            '100%{transform:translateX(calc(-100% - 40px));opacity:0;}}',

            '@keyframes hy-wbc-shine{0%{opacity:0;}',
            '50%{opacity:1;}100%{opacity:0;}}',

            '.hy-wbc .ic{font-size:1.15em;margin-right:2px;}',
