    /* 手動編撰清單（自動掛載武魂時保留；在 shanhaijingSystems 合併） */
    Data.SHJ_BEASTS_MANUAL = Data.SHJ_BEASTS.slice();

    /* 依 id 取 */
    Data.SHJ_BEAST_BY_ID = {};
    Data.SHJ_BEASTS.forEach(function (b) { Data.SHJ_BEAST_BY_ID[b.id] = b; });

    /* 山海經地圖異獸 id → 武魂定義 id（與 WUHUNS 不一致時） */
    Data.SHJ_WUHUN_ALIAS = {
        jiuweihu: 'fox',
        yingshao: 'yingzhao',
        lin: 'qilin',
        hanba: 'nvba',
        shayu: 'suanni',
        bilin: 'bifang',
        wenzhu: 'wenyaoyu',
        ranyi: 'ranyiyu',
        xueji: 'xiquzhu',
        baifeng: 'fenghuang',
        chiwen: 'lin',
        xuanbei: 'shenlong'
    };

    /** 對應的武魂定義（必須有 art）；無則 null */
    Data.shjWuhunDefOf = function (beast) {
        if (!beast) return null;
        var list = Data.WUHUNS;
        var byId = Data.WUHUN_BY_ID;
        if (!list || !list.length || !byId) return null;

        var wid = beast.wuhunId || Data.SHJ_WUHUN_ALIAS[beast.id] || beast.id;
        var def = byId[wid];
        if (def && def.art) return def;

        var nm = String(beast.name || '');
        var i, w;
        for (i = 0; i < list.length; i++) {
            w = list[i];
            if (!w.art) continue;
            if (w.name === nm) return w;
            if (nm.length >= 2 && w.name.indexOf(nm) === 0) return w;
        }
        return null;
    };

    /** 武魂合成圖（含光圈，僅武魂系統用） */
    Data.shjWuhunArtOf = function (beast) {
        var def = Data.shjWuhunDefOf(beast);
        return def && def.art ? def.art : '';
    };

    /** 山海經地圖／遭遇戰：僅靈獸主體，不帶武魂光圈 */
    Data.shjWuhunMapArtOf = function (beast) {
        var def = Data.shjWuhunDefOf(beast);
        if (!def || !def.art) return '';
        if (Data.wuhunBodyOf) {
            var body = Data.wuhunBodyOf(def);
            if (body) return body;
        }
        if (/\.png$/i.test(def.art)) return def.art.replace(/\.png$/i, '_body.png');
        return def.art;
    };

    /* ══════════════════════════════════════════════════════
       山海經地圖生成規則（可在此調整）
       ══════════════════════════════════════════════════════ */
    Data.SHJ_CONFIG = {
        mapW: 5121,
        mapH: 2880,
        perRegionMin: 2,
        perRegionMax: 3,
        respawnMs: 6 * 60 * 60 * 1000,
        padX: 0.20,
        padY: 0.22,
        /* ⭐ 遭遇戰強度：公式基底 + 插值同 Lv 探索頭目下限 + 隊伍人數加成 */
        combat: {
            hpFlat: 320,
            hpPerLv: 148,
            atkFlat: 38,
            atkPerLv: 7.4,
            defFlat: 22,
            defPerLv: 5.2,
            rewardMul: 1.15,
            partyMulBase: 0.52,
            partyMulPerMember: 0.19
        }
    };

    Data.shjRoot = function () {
        var cs = window.HY && window.HY.game && window.HY.game.charSys;
        return cs && cs.rootState ? cs.rootState : null;
    };

    Data.shjEnsureState = function (root) {
        if (!root) return;
        if (!root.shjWorld || typeof root.shjWorld !== 'object') root.shjWorld = {};
        if (!Array.isArray(root.shjWorld.spawns)) root.shjWorld.spawns = [];
    };

    function shjShuffle(arr) {
        var a = arr.slice();
        var i, j, t;
        for (i = a.length - 1; i > 0; i--) {
            j = Math.floor(Math.random() * (i + 1));
            t = a[i]; a[i] = a[j]; a[j] = t;
        }
        return a;
    }

    Data.shjPickCoords = function (region, slotIndex, slotTotal) {
        var cfg = Data.SHJ_CONFIG;
        var cellW = cfg.mapW / 3;
        var cellH = cfg.mapH / 3;
        var col = region % 3;
        var row = Math.floor(region / 3);
        var baseX = col * cellW;
        var baseY = row * cellH;
        var padX = cellW * cfg.padX;
        var padY = cellH * cfg.padY;
        var slotX = slotIndex % 2;
        var slotY = Math.floor(slotIndex / 2);
        var rx = baseX + padX + (cellW - padX * 2) * (0.22 + slotX * 0.56) * 0.85;
        var ry = baseY + padY + (cellH - padY * 2) * (0.25 + slotY * 0.5) * 0.8;
        rx += (Math.random() - 0.5) * cellW * 0.12;
        ry += (Math.random() - 0.5) * cellH * 0.14;
        return { x: Math.round(rx), y: Math.round(ry) };
    };

    Data.shjAddSpawn = function (root, region, beastId) {
        var pool = Data.shjBeastsInRegion(region);
        if (!pool.length) return null;
        var pick = pool[Math.floor(Math.random() * pool.length)];
        if (beastId) pick = Data.SHJ_BEAST_BY_ID[beastId] || pick;
        var key = 'shj_' + region + '_' + pick.id + '_' + Date.now().toString(36) +
            '_' + Math.floor(Math.random() * 1e4);
        var pos = Data.shjPickCoords(region, root.shjWorld.spawns.length % 3, 3);
        var row = {
            key: key,
            beastId: pick.id,
            region: region,
            x: pos.x,
            y: pos.y,
            bornAt: Date.now()
        };
        root.shjWorld.spawns.push(row);
        return row;
    };

    /** 同步地圖異獸：擊敗消失、逾時重生、各區補滿 */
    Data.shjSyncSpawns = function () {
        var root = Data.shjRoot();
        if (!root) return [];
        Data.shjEnsureState(root);
        var cfg = Data.SHJ_CONFIG;
        var now = Date.now();
        var list = root.shjWorld.spawns;

        list.forEach(function (s) {
            if (s && s.defeatedAt && (now - s.defeatedAt >= cfg.respawnMs)) {
                delete s.defeatedAt;
                var p = Data.shjPickCoords(s.region, Math.floor(Math.random() * 3), 3);
                s.x = p.x;
                s.y = p.y;
                s.bornAt = now;
                var bRe = Data.SHJ_BEAST_BY_ID[s.beastId];
                if (Data.shjInitSpawnRow) Data.shjInitSpawnRow(s, bRe);
            }
        });

        if (!list.length) {
            for (var r0 = 0; r0 < 9; r0++) {
                var n0 = cfg.perRegionMin +
                    Math.floor(Math.random() * (cfg.perRegionMax - cfg.perRegionMin + 1));
                var pool0 = shjShuffle(Data.shjBeastsInRegion(r0));
                for (var k0 = 0; k0 < Math.min(n0, pool0.length); k0++) {
                    Data.shjAddSpawn(root, r0, pool0[k0].id);
                }
            }
        }

        for (var region = 0; region < 9; region++) {
            var active = list.filter(function (s) {
                return s && s.region === region && !s.defeatedAt;
            });
            var need = cfg.perRegionMin - active.length;
            for (var k = 0; k < need; k++) {
                Data.shjAddSpawn(root, region);
            }
        }

        return list.filter(function (s) { return s && !s.defeatedAt; });
    };

    Data.shjMarkDefeated = function (spawnKey) {
        if (!spawnKey) return;
        var root = Data.shjRoot();
        if (!root) return;
        Data.shjEnsureState(root);
        root.shjWorld.spawns.forEach(function (s) {
            if (s && s.key === spawnKey) s.defeatedAt = Date.now();
        });
    };

    Data.shjRulesText = function () {
        var h = Math.round((Data.SHJ_CONFIG.respawnMs || 0) / 3600000);
        return '異獸規則：九宮各區隨機 ' + Data.SHJ_CONFIG.perRegionMin + '~' +
            Data.SHJ_CONFIG.perRegionMax + ' 隻（僅有武魂圖者）· 擊敗後消失 · ' +
            h + ' 小時後原地重生';
    };

    var SHJ_RARITY_LV = { common: 0, rare: 10, epic: 22, legend: 38 };
    var SHJ_RARITY_BOSS_MUL = { common: 0.84, rare: 0.98, epic: 1.1, legend: 1.28 };
    var SHJ_BOSS_NAME = /【頭目】|頭目|首領|霸主|宗師|統帥|黑榜|劍神|魔師|女帝|邪帝|武神|神遊|仙祖|終極/;
    var SHJ_ELEMENT_ZH = {
        wood: '木', fire: '火', water: '水', earth: '土', metal: '金',
        ice: '冰', thunder: '雷', poison: '毒', dark: '暗', light: '光'
    };

    var _shjBossPool = null;
    function shjBossSamplePool() {
        if (_shjBossPool) return _shjBossPool;
        var list = [];
        var maps = Data.MAPS || {};
        Object.keys(maps).forEach(function (mid) {
            var m = maps[mid];
            if (!m || !Array.isArray(m.enemies)) return;
            m.enemies.forEach(function (e) {
                if (!e || !(e.hp > 0) || !SHJ_BOSS_NAME.test(String(e.name || ''))) return;
                list.push({
                    lv: Number(e.lv) || 1,
                    hp: Number(e.hp) || 1,
                    atk: Number(e.atk) || 1,
                    def: Number(e.def) || 0,
                    hit: Number(e.hit) || 90,
                    eva: Number(e.eva) || 0,
                    crit: Number(e.crit) || 0,
                    critRes: Number(e.critRes) || 0
                });
            });
        });
        list.sort(function (a, b) { return a.lv - b.lv; });
        _shjBossPool = list;
        return list;
    }

    function shjLerpLog(a, b, t) {
        var va = a > 0 ? Math.log(a) : 0;
        var vb = b > 0 ? Math.log(b) : 0;
        return Math.round(Math.exp(va + (vb - va) * t));
    }

    /** 依等級插值時空探索「頭目級」怪物，作為異獸強度下限 */
    Data.shjExploreBossBenchmark = function (lv) {
        var pool = shjBossSamplePool();
        if (!pool.length) return null;
        var target = Math.max(1, Number(lv) || 1);
        if (target <= pool[0].lv) {
            var s0 = target / Math.max(1, pool[0].lv);
            return {
                hp: Math.max(1, Math.round(pool[0].hp * s0)),
                atk: Math.max(1, Math.round(pool[0].atk * s0)),
                def: Math.round(pool[0].def * s0),
                hit: pool[0].hit, eva: Math.round(pool[0].eva * s0),
                crit: pool[0].crit, critRes: pool[0].critRes
            };
        }
        var last = pool[pool.length - 1];
        if (target >= last.lv) {
            var prev = pool[pool.length - 2] || last;
            var span = Math.max(1, last.lv - prev.lv);
            var rateHp = Math.pow(last.hp / Math.max(1, prev.hp), 1 / span);
            var rateAtk = Math.pow(last.atk / Math.max(1, prev.atk), 1 / span);
            var rateDef = Math.pow(Math.max(1, last.def) / Math.max(1, prev.def), 1 / span);
            var extra = target - last.lv;
            return {
                hp: Math.round(last.hp * Math.pow(rateHp, extra * 0.92)),
                atk: Math.round(last.atk * Math.pow(rateAtk, extra * 0.92)),
                def: Math.round(last.def * Math.pow(rateDef, extra * 0.92)),
                hit: last.hit, eva: last.eva, crit: last.crit, critRes: last.critRes
            };
        }
        var i;
        for (i = 1; i < pool.length; i++) {
            if (pool[i].lv >= target) break;
        }
        var hi = pool[i];
        var lo = pool[i - 1];
        var t = (target - lo.lv) / Math.max(1, hi.lv - lo.lv);
        return {
            hp: shjLerpLog(lo.hp, hi.hp, t),
            atk: shjLerpLog(lo.atk, hi.atk, t),
            def: shjLerpLog(lo.def, hi.def, t),
            hit: Math.round(lo.hit + (hi.hit - lo.hit) * t),
            eva: Math.round(lo.eva + (hi.eva - lo.eva) * t),
            crit: Math.round(lo.crit + (hi.crit - lo.crit) * t),
            critRes: Math.round(lo.critRes + (hi.critRes - lo.critRes) * t)
        };
    };

    /** 山海經遭遇戰：依異獸與武魂定義組出敵人模板 */
    Data.shjBuildChallengeEnemy = function (beast) {
        if (!beast) return null;
        var def = Data.shjWuhunDefOf(beast);
        if (!def) return null;

        var lv = 1;
        var game = window.HY && window.HY.game;
        if (game && game.charSys) {
            lv = Math.max(1, Number(game.charSys.state && game.charSys.state.lv) || 1);
            if (game.partySys && typeof game.partySys.getPartyMembers === 'function') {
                (game.partySys.getPartyMembers() || []).forEach(function (m) {
                    lv = Math.max(lv, Number(m && m.lv) || 1);
                });
            }
        }
        var elv = Math.max(def.minLv || 1, lv + (SHJ_RARITY_LV[beast.rarity] || 0));
        var rMul = beast.rarity === 'legend' ? 2.55 : (beast.rarity === 'epic' ? 1.88 : (beast.rarity === 'rare' ? 1.42 : 1));
        var cCfg = (Data.SHJ_CONFIG && Data.SHJ_CONFIG.combat) || {};
        var hpCore = (Number(cCfg.hpFlat) || 320) + elv * (Number(cCfg.hpPerLv) || 148);
        var hp = Math.floor(hpCore * Math.pow(rMul, 1.32));
        var atkCore = (Number(cCfg.atkFlat) || 38) + elv * (Number(cCfg.atkPerLv) || 7.4);
        var atk = Math.floor(atkCore * Math.pow(rMul, 0.78));
        var defStat = Math.floor(((Number(cCfg.defFlat) || 22) + elv * (Number(cCfg.defPerLv) || 5.2)) *
            Math.pow(rMul, 0.92));
        var partySize = 1;
        try {
            if (game && game.partySys && typeof game.partySys.getPartySize === 'function') {
                partySize = Math.max(1, Number(game.partySys.getPartySize()) || 1);
            }
        } catch (ePs) { partySize = 1; }
        var partyMul = (Number(cCfg.partyMulBase) || 0.52) +
            partySize * (Number(cCfg.partyMulPerMember) || 0.19);
        hp = Math.max(1, Math.round(hp * partyMul));
        atk = Math.max(1, Math.round(atk * partyMul));
        defStat = Math.max(0, Math.round(defStat * partyMul));

        var bench = Data.shjExploreBossBenchmark(elv);
        var bossFac = SHJ_RARITY_BOSS_MUL[beast.rarity] || 0.9;
        if (bench) {
            hp = Math.max(hp, Math.round(bench.hp * bossFac));
            atk = Math.max(atk, Math.round(bench.atk * bossFac));
            defStat = Math.max(defStat, Math.round(bench.def * bossFac));
        }

        var hitVal = Math.min(128, 92 + Math.floor(elv * 0.42) + (beast.rarity === 'legend' ? 4 : 0));
        var evaVal = Math.min(34, 8 + Math.floor(elv * 0.26) + Math.floor(rMul * 2));
        var critVal = Math.min(42, 10 + Math.floor(elv * 0.32) + (beast.rarity === 'legend' ? 6 : 0));
        var critResVal = Math.min(38, 6 + Math.floor(elv * 0.24) + Math.floor(rMul * 3));
        if (bench) {
            hitVal = Math.max(hitVal, Math.round(bench.hit * bossFac));
            evaVal = Math.max(evaVal, Math.round(bench.eva * bossFac));
            critVal = Math.max(critVal, Math.round(bench.crit * bossFac));
            critResVal = Math.max(critResVal, Math.round(bench.critRes * bossFac));
        }

        var rewMul = Number(cCfg.rewardMul) || 1.15;
        var skillName = def.skill || '異獸撲擊';
        var skillMult = beast.rarity === 'legend' ? 1.68 : (beast.rarity === 'epic' ? 1.52 : (beast.rarity === 'rare' ? 1.42 : 1.32));

        var enemy = {
            id: 'shj_' + beast.id,
            uid: 'shj_' + beast.id + '_' + Date.now(),
            name: '【山海】' + beast.name,
            lv: elv,
            hp: hp, maxHp: hp, atk: atk, def: defStat,
            hit: Math.min(135, hitVal),
            eva: Math.min(42, evaVal),
            crit: Math.min(48, critVal),
            critRes: Math.min(45, critResVal),
            atkSpd: Math.min(145, 100 + Math.floor(elv * 0.35) + (beast.rarity === 'epic' || beast.rarity === 'legend' ? 8 : 0)),
            exp: Math.floor(hp * 0.42 * rewMul),
            sp: Math.floor(hp * 0.28 * rewMul),
            gold: Math.floor(hp * 0.32 * rewMul),
            faction: '山海經・' + (beast.source || '佚卷'),
            skills: [{ name: skillName, mult: skillMult, effect: def.skillType === 'buff' ? 'normal' : 'pierce' }],
            isShjBeast: true,
            shjBeastMega: true,
            shjSpawnKey: beast._spawnKey || '',
            shjBeastId: beast.id,
            wuhunDefId: def.id,
            icon: def.icon || beast.icon || '🐾',
            sprite: Data.shjWuhunMapArtOf(beast) || '',
            element: def.element || 'earth'
        };
        if (Data.shjFinalizeEnemy) enemy = Data.shjFinalizeEnemy(enemy, beast) || enemy;
        return enemy;
    };

    /* 依區域取（region 0~8）；僅含已有武魂繪圖者 */
    Data.shjBeastsInRegion = function (regionIdx) {
        var r = Number(regionIdx);
        return Data.SHJ_BEASTS.filter(function (b) {
            if ((b.region || []).indexOf(r) < 0) return false;
            if (!Data.shjWuhunDefOf(b)) return false;
            return !!(Data.shjWuhunMapArtOf && Data.shjWuhunMapArtOf(b)) ||
                !!Data.shjWuhunArtOf(b);
        });
    };

    /* 依稀有度取顏色 */
    Data.shjRarityOf = function (rid) {
        return Data.SHJ_RARITY[rid] || Data.SHJ_RARITY.common;
    };

    if (window.console && console.log) {
        console.log('[HY 山海經] 手動編撰 ' + Data.SHJ_BEASTS.length +
            ' 種（武魂自動掛載由 shanhaijingSystems 合併）');
    }

