// js/uiShanHaiJingCodex.js — 山海圖鑑
window.HY = window.HY || {};
(function (HY) {
    'use strict';

    var LAYER_ID = 'hy-shj-codex';
    var STYLE_ID = 'hy-shj-codex-css';

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function ensureStyle() {
        if (document.getElementById(STYLE_ID)) return;
        var st = document.createElement('style');
        st.id = STYLE_ID;
        st.textContent = [
            '#hy-shj-codex{position:fixed;inset:0;z-index:9750;',
            'background:rgba(4,3,2,.82);display:flex;align-items:center;justify-content:center;',
            "font-family:'Microsoft JhengHei','PingFang TC',sans-serif;}",
            '.shj-cx{width:min(720px,94vw);max-height:86vh;display:flex;flex-direction:column;',
            'background:linear-gradient(160deg,#1e160c,#0d0a06);border:1px solid #7a5c32;',
            'border-radius:10px;box-shadow:0 12px 48px rgba(0,0,0,.75);}',
            '.shj-cx-hd{display:flex;align-items:center;gap:12px;padding:14px 18px;',
            'border-bottom:1px solid #4a3820;}',
            '.shj-cx-hd h3{margin:0;color:#e8c877;font-size:1.05rem;}',
            '.shj-cx-st{margin-left:auto;font-size:.78rem;color:#a8874a;}',
            '.shj-cx-x{background:#2a2116;border:1px solid #6b5636;color:#d8b878;',
            'border-radius:5px;padding:4px 10px;cursor:pointer;}',
            '.shj-cx-bd{overflow:auto;padding:12px 16px 16px;}',
            '.shj-cx-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px;}',
            '.shj-cx-card{border:1px solid #3d3020;border-radius:8px;padding:10px;',
            'background:rgba(12,9,6,.9);min-height:88px;}',
            '.shj-cx-card.unknown{opacity:.45;filter:grayscale(.85);}',
            '.shj-cx-card .nm{font-weight:bold;color:#f0e4c8;font-size:.88rem;}',
            '.shj-cx-card .meta{font-size:.72rem;color:#8a7a5e;margin-top:4px;line-height:1.5;}',
            '.shj-cx-card .rar{font-size:.7rem;margin-top:2px;}',
            '.shj-cx-craft{margin-top:6px;display:flex;flex-wrap:wrap;gap:4px;}',
            '.shj-cx-craft button{font-size:.68rem;padding:3px 6px;border-radius:4px;',
            'border:1px solid #6b4fb8;background:#1a1428;color:#d8c4ff;cursor:pointer;}',
            '.shj-cx-craft button:disabled{opacity:.4;cursor:not-allowed;}'
        ].join('');
        document.head.appendChild(st);
    }

    function buildCards() {
        var Data = HY.Data;
        if (!Data || !Data.SHJ_BEASTS) return '';
        var codex = {};
        var root = Data.shjRoot && Data.shjRoot();
        if (root && Data.shjEnsureState) {
            Data.shjEnsureState(root);
            codex = root.shjWorld.codex || {};
        }
        var stats = Data.shjCodexStats ? Data.shjCodexStats() : { total: 0, seen: 0, kills: 0 };
        var html = '';
        var list = (Data.SHJ_BEASTS || []).filter(function (b) {
            return Data.shjWuhunMapArtOf && Data.shjWuhunMapArtOf(b);
        });
        list.sort(function (a, b) {
            var ra = { common: 0, rare: 1, epic: 2, legend: 3 };
            return (ra[b.rarity] || 0) - (ra[a.rarity] || 0) || String(a.name).localeCompare(b.name);
        });
        list.forEach(function (b) {
            var c = codex[b.id] || {};
            var known = !!(c.seen || c.kills);
            var rar = Data.shjRarityOf ? Data.shjRarityOf(b.rarity) : { name: b.rarity, color: '#ccc' };
            var ri = Array.isArray(b.region) ? b.region[0] : b.region;
            var reg = (typeof ri === 'number' && Data.SHJ_REGIONS) ? Data.SHJ_REGIONS[ri] : '';
            var setTpl = (typeof ri === 'number' && Data.shjSetByRegion) ? Data.shjSetByRegion(ri) : null;
            var setLine = '';
            if (known && c.setCodex && setTpl) {
                var slots = Number(c.craftSlots) || 1;
                var bonusPct = Math.round((Number(c.dropBonus) || 0) * 100);
                var coreTxt = c.corePiece ? ('核心件：' + c.corePiece) : '掉落：同區套裝隨機件';
                var pieceLbl = { weapon: '武', body: '身', helmet: '頭', gloves: '手', boots: '足' };
                var order = (Data.SHJ_SET_PIECE_ORDER || ['weapon', 'body', 'helmet', 'gloves', 'boots']);
                var craftBtns = '<div class="shj-cx-craft">';
                order.forEach(function (pk, idx) {
                    var on = idx < slots;
                    craftBtns += '<button type="button" data-shj-craft="' + esc(b.id) + '" data-piece="' + pk + '"' +
                        (on ? '' : ' disabled') + '>⚒' + esc(pieceLbl[pk] || pk) + '</button>';
                });
                craftBtns += '</div>';
                var arch = setTpl.archetype ? ('【' + setTpl.archetype + '】' + esc(setTpl.archetypeDesc || '') + '<br>') : '';
                setLine = '<div class="meta" style="color:#a78bfa;margin-top:6px;">' + arch + '套裝圖錄【' +
                    esc(setTpl.name) + '】5 件　掉率+' + bonusPct + '%　打造槽 ' + slots + '/5<br>' +
                    esc(coreTxt) + '（2 混沌石）' + craftBtns + '</div>';
            } else if (known && !c.setCodex) {
                setLine = '<div class="meta" style="color:#64748b;">首鎮壓後解鎖套裝圖錄</div>';
            }
            html +=
                '<div class="shj-cx-card' + (known ? '' : ' unknown') + '">' +
                '<div class="nm">' + esc(known ? b.name : '？？？') + '</div>' +
                '<div class="rar" style="color:' + rar.color + '">' + esc(rar.name) +
                (reg ? ' · ' + esc(reg) : '') + '</div>' +
                '<div class="meta">' +
                (known ? ('目擊 ' + (c.seen ? '✓' : '—') + '　鎮壓 ' + (Number(c.kills) || 0) + ' 次') : '尚未記錄') +
                '</div>' + setLine + '</div>';
        });
        return { body: html, stats: stats };
    }

    function open() {
        ensureStyle();
        close();
        var built = buildCards();
        var layer = document.createElement('div');
        layer.id = LAYER_ID;
        layer.innerHTML =
            '<div class="shj-cx" role="dialog">' +
            '<div class="shj-cx-hd">' +
            '<h3>📖 山海圖鑑</h3>' +
            '<span class="shj-cx-st">收錄 ' + built.stats.seen + ' / ' + built.stats.total +
            '　累計鎮壓 ' + built.stats.kills + '</span>' +
            '<button type="button" class="shj-cx-x" id="shj-cx-close">✖</button>' +
            '</div>' +
            '<div class="shj-cx-bd"><div class="shj-cx-grid">' + built.body + '</div></div>' +
            '</div>';
        document.body.appendChild(layer);
        layer.addEventListener('click', function (e) {
            if (e.target === layer) close();
        });
        layer.querySelector('#shj-cx-close').addEventListener('click', close);
        layer.querySelector('.shj-cx-bd').addEventListener('click', function (ev) {
            var btn = ev.target && ev.target.closest ? ev.target.closest('[data-shj-craft]') : null;
            if (!btn || btn.disabled) return;
            var beastId = btn.getAttribute('data-shj-craft');
            var piece = btn.getAttribute('data-piece');
            var poe = window.HY.game && window.HY.game.poeSys;
            if (!poe || typeof poe.craftShjSetPiece !== 'function') return;
            var res = poe.craftShjSetPiece(beastId, piece);
            if (!res || !res.ok) {
                if (window.HY.game && window.HY.game.logger) {
                    window.HY.game.logger.add('⚠️ 套裝打造：' + (res && res.why ? res.why : '失敗'), 'system');
                }
                return;
            }
            close();
            open();
        });
        document.addEventListener('keydown', escClose);
    }

    function escClose(e) {
        if (e.key === 'Escape') close();
    }

    function close() {
        var el = document.getElementById(LAYER_ID);
        if (el && el.parentNode) el.parentNode.removeChild(el);
        document.removeEventListener('keydown', escClose);
    }

    HY.UIShanHaiJingCodex = { open: open, close: close };
})(window.HY);

