            var ro = Object.assign({}, firstOpts || {});
            if (typeof ro.reqLv !== 'number') {
                ro.reqLv = (itemInst && typeof itemInst.reqLv === 'number') ? itemInst.reqLv
                         : nz(this.charSys && this.charSys.state && this.charSys.state.lv, 30);
            }
