// js/fossilSystem.js  (v1)
// PoE1 化石工藝系統
//
// 職責：
//   ⭐ ensureState()            —— rootState.fossils 倉庫
//   ⭐ addFossil / count        —— 礦坑掉落呼叫
//   ⭐ canApply(id, item)       —— 使用前檢核
//   ⭐ applyFossilToSelected()  —— 用化石重骰裝備（保證/排除/加權/追量）
//
// 載入順序必須在 poeCraftSystem.js 之後（會呼叫 getSelectedCraftItem /
// rollRareMods / generateRareTitle）。
window.HY = window.HY || {};
(function () {
    function num(v, d) {
        return (typeof v === 'number' && isFinite(v)) ? v : (d || 0);
    }
    class FossilSystem {
        constructor(charSys, logger, poeSys) {
            this.charSys = charSys;
            this.logger = logger;
            this.poeSys = poeSys || null;
        }
        // ──────────────────────────────────────────────────────────
        //  倉庫
        // ──────────────────────────────────────────────────────────
        ensureState() {
            var root = this.charSys && this.charSys.rootState;
            if (!root) return {};
            if (!root.fossils || typeof root.fossils !== 'object' || Array.isArray(root.fossils)) {
                root.fossils = {};
            }
            Object.keys(root.fossils).forEach(function (k) {
                if (typeof root.fossils[k] !== 'number' || !isFinite(root.fossils[k])) {
                    root.fossils[k] = num(root.fossils[k], 0);
                }
            });
            return root.fossils;
        }
        wallet() { return this.ensureState(); }
        count(id) { return num(this.wallet()[id], 0); }
        addFossil(id, n) {
            if (!id) return 0;
            var D = window.HY.Data || {};
            if (D.FOSSILS && !D.FOSSILS[id]) {
                console.warn('[HY Fossil] 未知化石 id：' + id);
                return 0;
            }
            var c = (typeof n === 'number' && isFinite(n) && n > 0) ? Math.floor(n) : 1;
            var w = this.wallet();
            w[id] = num(w[id], 0) + c;
            return w[id];
        }
        spend(id, n) {
            var c = (typeof n === 'number' && isFinite(n) && n > 0) ? Math.floor(n) : 1;
            var w = this.wallet();
            if (num(w[id], 0) < c) return false;
            w[id] -= c;
            if (w[id] <= 0) delete w[id];
            return true;
        }
        data(id) {
            var D = window.HY.Data || {};
            return (D.FOSSILS && D.FOSSILS[id]) || null;
        }
        totalCount() {
            var w = this.wallet(), t = 0;
            Object.keys(w).forEach(function (k) { t += num(w[k], 0); });
            return t;
        }
        kindCount() {
            var w = this.wallet(), t = 0;
            Object.keys(w).forEach(function (k) { if (num(w[k], 0) > 0) t += 1; });
            return t;
        }
        // ──────────────────────────────────────────────────────────
        //  檢核
        // ──────────────────────────────────────────────────────────
        canApply(fossilId, item) {
            var f = this.data(fossilId);
            if (!f) return { ok: false, why: '未知化石' };
            if (!item) return { ok: false, why: '請先選擇改造目標' };
            if (this.count(fossilId) <= 0) return { ok: false, why: '尚未持有【' + f.name + '】' };
            if (item.corrupted) return { ok: false, why: '此裝備已汙染，無法再改造' };
            if (item.rarity === 'unique') return { ok: false, why: '傳奇暗金詞綴固定，化石無法作用' };
            if (item.rarity === 'magic') {
                return { ok: false, why: '化石只能作用於【普通(白裝)】或【稀有(黃裝)】，藍裝請先用重鑄石洗白' };
            }
            return { ok: true, why: '' };
        }
        // ──────────────────────────────────────────────────────────
        //  工藝
        // ──────────────────────────────────────────────────────────
        buildOpts(f) {
            var D = window.HY.Data || {};
            return {
                guaranteeTags: f.guarantee || [],
                forbidTags: f.forbid || [],
                tierWeights: D.fossilTierWeights ? D.fossilTierWeights(f) : null,
                extraMods: f.extraMods || 0
            };
        }
        /* ⭐ 保證詞綴的落實方式：
           骰完之後檢查是否真的出現「保證標籤」的詞綴；
           沒有的話，挑一條最弱的換成保證池裡的一條。
           這樣才是字面上的「保證」，而不是「有機會」。 */
        enforceGuarantee(item, f, poe) {
            var D = window.HY.Data || {};
            var tags = f.guarantee || [];
            if (!tags.length || !D.fossilTagsOfGroup) return null;
            item.prefixes = item.prefixes || [];
            item.suffixes = item.suffixes || [];
            function listHasTag(list) {
                for (var i = 0; i < list.length; i++) {
                    var tg = D.fossilTagsOfGroup({ groupId: list[i].groupId, statKey: list[i].statKey });
                    for (var j = 0; j < tags.length; j++) {
                        if (tg.indexOf(tags[j]) !== -1) return true;
                    }
                }
                return false;
            }
            if (listHasTag(item.prefixes) || listHasTag(item.suffixes)) return null;
            /* 需要補一條：先找符合標籤的群組 */
            var opts = this.buildOpts(f);
            opts.guaranteeTags = tags;
            var D2 = D;
            function poolHasTag(pool) {
                return pool.filter(function (g) {
                    var tg = D2.fossilTagsOfGroup(g);
                    for (var k = 0; k < tags.length; k++) {
                        if (tg.indexOf(tags[k]) !== -1) return true;
                    }
                    return false;
                });
            }
            /* ⭐ 依裝備部位取詞綴池（舊的通用池已移除）
               呼叫 poeCraftSystem._poolFor 以保持與工藝系統同一來源。 */
            var craft = window.HY.game && window.HY.game.poeSys;
            var preAll = [], sufAll = [];
            if (craft && typeof craft._poolFor === 'function') {
                preAll = craft._poolFor(item, true) || [];
                sufAll = craft._poolFor(item, false) || [];
            } else {
                var M = window.HY.PoeAffixMap;
                var slot = (item && item.slotType) || 'ring';
                if (M && typeof M.poolFor === 'function') {
                    preAll = M.poolFor(slot, true) || [];
                    sufAll = M.poolFor(slot, false) || [];
                }
            }
            /* ⭐ 改用部位過濾池（呼叫端已透過 poeCraft._poolFor 取得正確池） */
            var prePool = poolHasTag(preAll);
            var sufPool = poolHasTag(sufAll);
            /* 選邊規則：
               1. 只有一邊有符合標籤的群組 → 用那一邊
               2. 兩邊都有 → 選目前條數較少的一邊（避免滿邊塞不進去）
               3. 該邊已滿 3 條 → 換掉最弱的（由下面處理） */
            var usePrefix = null;
            var pool = null;
            if (prePool.length && !sufPool.length) {
                usePrefix = true; pool = preAll;
            } else if (!prePool.length && sufPool.length) {
                usePrefix = false; pool = sufAll;
            } else if (prePool.length && sufPool.length) {
                usePrefix = item.prefixes.length <= item.suffixes.length;
                pool = usePrefix ? preAll : sufAll;
            }
            if (!pool) return null;
            var list = usePrefix ? item.prefixes : item.suffixes;
            var mod = null;
            /* 該邊滿了就換掉最弱的一條；否則 rollOneAffix 會因 groupId 去重
               找不到候選而回傳 null。 */
            if (list.length >= 3) {
                var weakest = 0;
                for (var wi = 1; wi < list.length; wi++) {
                    if (num(list[wi].val, 0) < num(list[weakest].val, 0)) weakest = wi;
                }
                list.splice(weakest, 1);
            }
            try { mod = poe.rollOneAffix(pool, list, opts); } catch (e) { mod = null; }
            if (!mod) return null;
            list.push(mod);
            return mod;
        }
        applyFossilToSelected(fossilId) {
            var f = this.data(fossilId);
            if (!f) return false;
            var poe = this.poeSys || (window.HY.game && window.HY.game.poeSys);
            if (!poe) {
                this._log('⚠️ 工藝系統未載入，無法使用化石。', 'system');
                return false;
            }
            var target = null;
            try { target = poe.getSelectedCraftItem(); } catch (e) { target = null; }
            if (!target) {
                this._log('⚠️ 請先在裝備欄或行囊中點選「💎 改造」指定一件裝備！', 'system');
                return false;
            }
            var chk = this.canApply(fossilId, target);
            if (!chk.ok) {
                this._log('❌ ' + chk.why, 'system');
                return false;
            }
            this.spend(fossilId, 1);
            var opts = this.buildOpts(f);
            var wasRarity = target.rarity || 'normal';
            target.rarity = 'rare';
            if (!target.rareTitle && typeof poe.generateRareTitle === 'function') {
                target.rareTitle = poe.generateRareTitle();
            }
            var before = (target.prefixes || []).length + (target.suffixes || []).length;
            if (typeof poe.rollRareMods === 'function') {
                poe.rollRareMods(target, opts);
            }
            /* 保證詞綴：骰完後檢查並補上（真正落實「保證」語意） */
            var ensured = this.enforceGuarantee(target, f, poe);
            /* 鎏金化石：額外給一條固定強力詞綴（直接吃得到屬性的 statKey） */
            if (f.extraImplicit) {
                var gildPool = [
                    { statKey: 'atk', label: '鎏金攻擊', unit: '', val: 320 },
                    { statKey: 'maxHp', label: '鎏金氣血', unit: '', val: 1800 },
                    { statKey: 'def', label: '鎏金防禦', unit: '', val: 260 },
                    { statKey: 'crit', label: '鎏金爆擊', unit: '%', val: 18 }
                ];
                var gp = gildPool[Math.floor(Math.random() * gildPool.length)];
                target.prefixes = target.prefixes || [];
                target.prefixes.push({
                    groupId: 'fossil_gilded_implicit',
                    statKey: gp.statKey,
                    label: gp.label,
                    unit: gp.unit,
                    tier: 0,
                    tName: '鎏金之',
                    min: gp.val,
                    max: gp.val,
                    val: gp.val,
                    fossilId: f.id
                });
                /* 超過 3 條時移除最弱的一條前綴（保留鎏金） */
                if (target.prefixes.length > 3) {
                    var weakest = 0;
                    for (var i = 0; i < target.prefixes.length - 1; i++) {
                        if (num(target.prefixes[i].val, 0) < num(target.prefixes[weakest].val, 0)) weakest = i;
                    }
                    target.prefixes.splice(weakest, 1);
                }
            }
            try { this.charSys.clampVitals(); } catch (e) { }
            var after = (target.prefixes || []).length + (target.suffixes || []).length;
            var rarityTxt = (wasRarity !== 'rare') ? '，並晉升為稀有黃裝' : '，重骰所有隨機詞綴';
            this._log('🪨 使用【' + f.name + '】：【' + target.name + '】' + rarityTxt +
                '，產出 ' + after + ' 條詞綴（原 ' + before + ' 條）。' +
                (ensured ? ' 保證詞綴：「' + ensured.tName + ' ' + ensured.label + '」。' : '') +
                (f.forbid.length ? ' 已排除 ' + f.forbid.length + ' 類詞綴。' : ''), 'combat');
            return true;
        }
        // 供 UI 用：目前持有、且可作用於該裝備的化石
        availableFor(item) {
            var D = window.HY.Data || {};
            var out = [];
            if (!D.FOSSIL_ORDER) return out;
            for (var i = 0; i < D.FOSSIL_ORDER.length; i++) {
                var id = D.FOSSIL_ORDER[i];
                var c = this.count(id);
                if (c <= 0) continue;
                out.push({ id: id, count: c, ok: this.canApply(id, item).ok });
            }
            return out;
        }
        _log(msg, type) {
            try {
                if (this.logger && typeof this.logger.add === 'function') {
                    this.logger.add(msg, type || 'system');
                } else if (window.console) {
                    console.log('[HY Fossil] ' + msg);
                }
            } catch (e) { }
        }
    }
    window.HY.FossilSystem = FossilSystem;
})();
/* --- combatArbiter.js --- */
// js/combatArbiter.js
// ⚖️ 戰鬥仲裁器 —— 確保「同一時間只能進行一種戰鬥系統」
//
// 三種戰鬥系統：
//   ① normal  —— 一般戰鬥（主畫面）
//   ② atlas   —— 異界輿圖打圖戰鬥
//   ③ delve   —— 地心礦坑戰鬥
//
// 規則：
//   · 任何一種進行中，其他兩種都無法開始（會被拒絕並提示）
//   · 提供 activeSystem() 查詢目前進行中的系統
//   · 各系統在開戰前必須呼叫 canStart(sys)，開戰後呼叫 claim(sys)，結束時 release(sys)
window.HY = window.HY || {};
(function () {
    'use strict';

    var SYS = {
        NORMAL: 'normal',
        ATLAS: 'atlas',
        DELVE: 'delve'
    };

    var SYS_NAME = {
        normal: '一般戰鬥',
        atlas: '異界輿圖戰鬥',
        delve: '地心礦坑戰鬥'
    };

    var current = null;   // 目前進行中的系統 id

    /** 目前進行中的戰鬥系統（'normal' / 'atlas' / 'delve' / null） */
    function activeSystem() {
        /* 主動偵測（避免 release 遺漏造成永久鎖定） */
        var g = window.HY.game || {};

        /* 輿圖優先（它會接管 combatCore 的 enemies） */
        var atlas = g.atlasSys;
        if (atlas && typeof atlas.isInMap === 'function' && atlas.isInMap()) {
            current = SYS.ATLAS;
            return current;
        }
        /* 礦坑 */
        var db = g.delveBattle;
        if (db && db.isActive) {
            current = SYS.DELVE;
            return current;
        }
        /* 一般戰鬥 */
        var cb = g.combatSys;
        if (cb) {
            var alive = (cb.enemies || []).filter(function (e) {
                return e && (e.currentHp || 0) > 0;
            });
            if (alive.length > 0) {
                current = SYS.NORMAL;
                return current;
            }
        }
        /* 都沒有在打 → 若 current 還留著就清掉 */
        if (current) current = null;
        return null;
    }

    /** 是否可以開始指定系統的戰鬥
        @returns { ok:true } 或 { ok:false, why } */
    function canStart(sysId) {
        var act = activeSystem();
        if (!act) return { ok: true };
        if (act === sysId) return { ok: true };   // 已在該系統中，允許續戰
        return {
            ok: false,
            why: '目前正在進行【' + (SYS_NAME[act] || act) + '】，' +
                 '請先結束後再開始【' + (SYS_NAME[sysId] || sysId) + '】'
        };
    }

    /** 標記某系統開始戰鬥 */
    function claim(sysId) {
        current = sysId;
    }

    /** 標記某系統結束戰鬥 */
    function release(sysId) {
        if (!sysId || current === sysId) current = null;
    }

    /** 名稱查詢（給 UI 顯示用） */
    function nameOf(sysId) {
        return SYS_NAME[sysId] || String(sysId || '');
    }

    /** 是否為指定系統在戰鬥中 */
    function isActive(sysId) {
        return activeSystem() === sysId;
    }

    /** 統一提示（若 uiAtlas 有 toast 就用它） */
    function toast(msg, isErr) {
        try {
            if (window.HY.uiAtlas && typeof window.HY.uiAtlas._toast === 'function') {
                window.HY.uiAtlas._toast(msg, !!isErr);
                return;
            }
        } catch (e) { }
        try {
            if (window.HY.uiDelve && typeof window.HY.uiDelve._toast === 'function') {
                window.HY.uiDelve._toast(msg, !!isErr);
                return;
            }
        } catch (e2) { }
        /* 最後手段：寫進日誌 */
        try {
            var g = window.HY.game;
            if (g && g.logger && typeof g.logger.add === 'function') {
                g.logger.add((isErr ? '⛔ ' : 'ℹ️ ') + msg, 'system');
            }
        } catch (e3) { }
    }

    window.HY.CombatArbiter = {
        SYS: SYS,
        activeSystem: activeSystem,
        canStart: canStart,
        claim: claim,
        release: release,
        isActive: isActive,
        nameOf: nameOf,
        toast: toast
    };
})();

