    xinfa:    { data: 'XINFA',        store: 'xinfa',    label: '心法', icon: '📜', building: 'martialHall', single: true },
    qinggong: { data: 'QINGGONG',     store: 'qinggong', label: '輕功', icon: '💨', building: 'martialHall', single: true }
