    this.guildClampVitals(adv);
    this.guildLog('📖 【' + adv.name + '】習得' + KINDS[kind].label + '【' + def._name + '】，耗 ' +
      chk.cost.sp + ' 武學點數、' + chk.cost.gold + ' 兩。', 'time');
