    var cost = this.advUpgradeCost(adv, def, lv);
    if (A.advSp < cost.sp) return { ok: false, msg: '武學點數不足（需 ' + cost.sp + '）' };
    if (this.charSys.rootState.gold < cost.gold) return { ok: false, msg: '銀兩不足（需 ' + cost.gold + ' 兩）' };
