    if (!Array.isArray(W.history)) W.history = [];
    if (!W.mvp || typeof W.mvp !== 'object') W.mvp = {};
    if (!W.stats || typeof W.stats !== 'object') W.stats = d.stats;
    for (k in d.stats) { if (W.stats[k] === undefined) W.stats[k] = 0; }
