    if (W.active.status === 'fighting') { this.log('⚠️ 討伐已開始，無法變更隊伍。', 'system'); return false; }
    var self = this;
    var friends = (friendIds || []).map(function (id) { return self.friendById(id); }).filter(Boolean);
