    if (pow <= 0) { this.log('⚠️ 隊伍戰力為 0，無法討伐。', 'system'); return false; }
    a.teamPower = pow;
    a.maxHp = Math.round(pow * num(C3.WB_HP_BASE, 0.85) * (1 + num(a.tier, 1) * 0.12) * num(this.fr3WbDef(a.bossId) && this.fr3WbDef(a.bossId).hpMul, 1));
