      if (num(root.gold, 0) < num(w.amount, 0)) { this.log('⚠️ 需 ' + num(w.amount, 0).toLocaleString() + ' 兩紋銀。', 'system'); return false; }
      root.gold = num(root.gold, 0) - num(w.amount, 0);
