          atkPct: sb.atkPct + sl * num(C6.SPIRIT_STAT_PER_LV, 0.012) + sm,
          defPct: sb.defPct + sl * num(C6.SPIRIT_STAT_PER_LV, 0.012) + sm,
          hpPct:  sb.hpPct  + sl * num(C6.SPIRIT_STAT_PER_LV, 0.012) + sm,
