    MOVE_CRAFT: true,
    MOVE_BAG: true,
    CRAFT_ID: 'poe-craft-bench',
    BAG_FILTER_SEL: '.inv-filter-bar',
    BAG_LIST_ID: 'inventory-list',
    COMPARE: true,          // 雙視窗對比
    GRID_COLS: 6,
    ORB_COLS: 10,           // 通貨倉庫每列格數
    TOOLTIP_DELAY: 70,
    VERBOSE: true,
    PREF_KEY: 'hy_bagov_pref_v8',
    LOCK_KEY: 'hy_bagov_lock_v8'
