      '<label class="eg-chk">' +
      '<input type="checkbox" id="bagov-ess-owned"' + (_pref.essenceOnlyOwned ? ' checked' : '') + '>' +
      '<span>只顯示持有</span>' +
      '</label>' +
      '<span class="eg-num">持有 <b>' + heldKinds + '</b> / ' + order.length + ' 種</span>' +
      '</div>';
    h += '<div class="eg-cells" style="grid-template-columns:repeat(' + n + ',minmax(0,1fr))">';
