  /* ===== poe_tool: craft-target art + synchronous re-decoration =====
     WHY: renderBag() rebuilds the original paperdoll / inventory list through
     refreshCraft() -> uiEquipMarket.renderInventoryTab(). That is synchronous,
     but the PoE-art decorators used to run from a throttled timer, so the
     freshly rebuilt nodes were PAINTED with their emoji for a frame or more.
     Calling the decorators right here, in the same synchronous block, means
     the swap happens before the browser paints - no visible flicker.
     ================================================================== */
  window.poeIconErr = function (img) {
    if (!img) return;
    var list = String(img.getAttribute('data-chain') || '').split('|');
    var i = parseInt(img.getAttribute('data-ci') || '0', 10) + 1;
    if (i < list.length) { img.setAttribute('data-ci', String(i)); img.src = list[i]; return; }
    img.style.display = 'none';
  };
  var POE_ICON_BASE = 'assets/poe-equipment/';
  var POE_CDN_BASE = 'https://web.poecdn.com/image/';
  function poeTplOf(id) {
    if (!id) return null;
    var d = window.HY.Data || {};
    var m = d.POE_BASES_BY_ID;
    if (m && m[id]) return m[id];
    var a = d.POE_BASES;
    if (Array.isArray(a)) {
      for (var i = 0; i < a.length; i++) { if (a[i] && a[i].id === id) return a[i]; }
    }
    return null;
  }
  function poeNearest(slotType, reqLv) {
    var d = window.HY.Data || {};
    var a = d.POE_BASES, pool = [], i;
    if (!Array.isArray(a)) return null;
    for (i = 0; i < a.length; i++) {
      if (a[i] && a[i].icon && String(a[i].slotType) === String(slotType)) pool.push(a[i]);
    }
    if (!pool.length) {
      for (i = 0; i < a.length; i++) { if (a[i] && a[i].icon) pool.push(a[i]); }
    }
    if (!pool.length) return null;
    var lv = Number(reqLv) || 1, best = null, bd = Infinity;
    for (i = 0; i < pool.length; i++) {
      var dd = Math.abs((Number(pool[i].reqLv) || 1) - lv);
      if (dd < bd) { bd = dd; best = pool[i]; }
    }
    return best;
  }
  function poeIconOf(it) {
    if (!it) return null;
    var t = poeTplOf(it.baseId);
    if (!t || !t.icon) t = poeNearest(it.slotType, it.reqLv);
    if (!t || !t.icon) return null;
    return { file: t.icon, path: t.iconPath || ('Art/2DItems/' + t.icon) };
  }
  function poeIconHtml(it, cls, px) {
    if (shjIsSetItem(it)) {
      var Data = window.HY.Data;
      if (Data && typeof Data.shjSetIconHtml === 'function') {
        return Data.shjSetIconHtml(it, px || 22);
      }
    }
    var ic = poeIconOf(it);
    if (!ic) return '';
    var chain = [POE_ICON_BASE + ic.file, POE_CDN_BASE + ic.path, POE_CDN_BASE + ic.path + '?w=1&h=1'];
    var c = cls || 'tb-icon';
    var p = px || 22;
    return '<img class="' + c + '" alt="" draggable="false"' +
      ' style="width:' + p + 'px;height:' + p + 'px;object-fit:contain;flex:0 0 auto;"' +
      ' data-chain="' + chain.join('|').replace(/&/g, '&amp;') + '"' +
      ' data-ci="0" src="' + chain[0] + '" onerror="poeIconErr(this)">';
  }
  function tgtIconHtml(it) { return poeIconHtml(it, 'tb-icon', 22); }
  function poeDecorateNow() {
    try {
      if (window.HY.PoeItemIcons && typeof window.HY.PoeItemIcons.decorate === 'function') {
        window.HY.PoeItemIcons.decorate();
      }
    } catch (e) {}
    try {
      if (window.HY.PoeUiFix && typeof window.HY.PoeUiFix.run === 'function') {
        window.HY.PoeUiFix.run();
      }
    } catch (e) {}
  }
  try { window.poeDecorateNow = poeDecorateNow; } catch (e) {}
