  function injectCSS() {
    if (document.getElementById('tabfix-style')) return;
    var host = document.head || document.documentElement;
    if (!host) return;
    var H = CFG.BTN_HEIGHT, P = CFG.BTN_PAD, F = CFG.BTN_FONT;
    var css = `
/* ══ .system-controls：單列橫向捲動工具列 ══
   ⚠️ 舊版用 flex-wrap:wrap，按鈕總寬超過視窗時會折到第二行，
      於是工具列高度在 30px / 60px 之間來回變動 ——
      只要順序或視窗寬度有一點變化，整排標籤就會「跳動」。
      改成 nowrap + 橫向捲動後高度永遠固定，不會再跳。 */
${CFG.CONTAINER_SEL}{
  display:flex !important;
  flex-wrap:nowrap !important;
  align-items:center !important;
  justify-content:flex-end !important;
  gap:6px !important;
  max-width:100% !important;
  height:${CFG.BTN_HEIGHT + 8}px !important;
  min-height:${CFG.BTN_HEIGHT + 8}px !important;
  overflow-x:auto !important;
  overflow-y:hidden !important;
  scrollbar-width:none !important;
  -ms-overflow-style:none !important;
}
${CFG.CONTAINER_SEL}::-webkit-scrollbar{height:0 !important;width:0 !important;}
/* ══ 每一顆按鈕：統一尺寸（★ 關鍵：flex:0 0 auto 修正寬條）══ */
${CFG.CONTAINER_SEL} > button,
${CFG.CONTAINER_SEL} > a,
${CFG.CONTAINER_SEL} > .hy-ext-btn,
.hy-ext-btn{
  flex:0 0 auto !important;
  width:auto !important;
  min-width:0 !important;
  max-width:none !important;
  height:${H}px !important;
  box-sizing:border-box !important;
  padding:0 ${P}px !important;
  margin:0 !important;
  font-size:${F} !important;
  line-height:${H - 2}px !important;
  white-space:nowrap !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  border-radius:6px !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  gap:5px !important;
  vertical-align:middle !important;
  animation:none !important;
}
/* 內部裝飾元素不要影響排版 */
.hy-ext-btn > span,
${CFG.CONTAINER_SEL} > button > span{
  display:inline-block !important;
  line-height:1 !important;
  flex:0 0 auto !important;
}
.hy-ext-btn .font-shine,
.hy-ext-btn .fr3-shine{display:none !important;}

/* ══ 窄螢幕：縮短內距 ══ */
@media (max-width:1100px){
  ${CFG.CONTAINER_SEL} > button,
  ${CFG.CONTAINER_SEL} > a,
  .hy-ext-btn{ padding:0 8px !important; font-size:.74rem !important; }
}
`;
    var st = document.createElement('style');
    st.id = 'tabfix-style';
    st.appendChild(document.createTextNode(css));
    host.appendChild(st);
  }
  /* ══════════════════════════════════════════════════════
     ④ 主流程
     ══════════════════════════════════════════════════════ */
  function container() {
    var c = document.querySelector(CFG.CONTAINER_SEL);
    if (c) return c;
    return document.querySelector(CFG.FALLBACK_SEL);
  }
  /* ══════════════════════════════════════════════════════
     ⭐ 尊重使用者拖曳後的順序
     ══════════════════════════════════════════════════════
     本檔每 700ms 會校正一次順序，而 uiTabDrag 讓使用者可以自由拖拉。
     兩者同時存在時，拖曳結果會在 0.7 秒後被這裡硬拉回 CFG.ORDER，
     使用者看到的就是「拖不動 / 拖完又跳回去」。

     解法：只要 localStorage 裡有拖曳存下的順序，就以那份為準；
     本檔只負責「尺寸統一 + 去重 + 補上未列出的按鈕」，
     不再干預已排序過的標籤。 */
  var DRAG_STORE_KEY = 'HUANGYI_TAB_ORDER_V2';
  function dragOrderKeys() {
    try {
      var raw = localStorage.getItem(DRAG_STORE_KEY);
      if (!raw) return null;
      var o = JSON.parse(raw);
      var seq = o && o[CFG.CONTAINER_SEL];
      if (!Array.isArray(seq) || !seq.length) return null;
      return seq;
    } catch (e) { return null; }
  }
  /* 把 seq 依拖曳紀錄排序（未記錄者排在後面，保持原相對順序） */
  function sortByDragOrder(seq) {
    var saved = dragOrderKeys();
    if (!saved) return seq;
    var rank = {};
    saved.forEach(function (k, i) { if (!(k in rank)) rank[k] = i; });
    var withRank = [], noRank = [];
    seq.forEach(function (el) {
      var k = el.getAttribute('data-tabfix') ? ('fix:' + el.getAttribute('data-tabfix'))
        : (el.getAttribute('data-tab') ? ('tab:' + el.getAttribute('data-tab'))
          : (el.id ? ('id:' + el.id) : ('txt:' + String(el.textContent || '').trim().slice(0, 18))));
      if (rank[k] !== undefined) withRank.push({ el: el, r: rank[k] });
      else noRank.push(el);
    });
    withRank.sort(function (a, b) { return a.r - b.r; });
    return withRank.map(function (x) { return x.el; }).concat(noRank);
  }
  function run() {
    if (!document.body) return false;
    injectCSS();
    var ctrl = container();
    if (!ctrl) return false;
    /* ⭐ v71：快捷插槽內的按鈕也要納入「已知按鈕」清單。
       ⚠️ 舊版只從 .system-controls 的子元素建立 keep，
          但第一輪已把「離線／畫面／字體／儲存」搬到 top-quick-slot，
          第二輪之後 keep 裡就完全沒有這四顆 → 順序校正失效
          （實測每次都停在「畫面→字體→儲存→離線」）。
       解法：先把插槽內的元素併進來一起分桶。 */
    var quickSlot0 = document.getElementById('top-quick-slot');
    var kids = Array.prototype.slice.call(ctrl.children).filter(isEl);
    if (quickSlot0) {
      Array.prototype.slice.call(quickSlot0.children).forEach(function (el) {
        if (isEl(el)) kids.push(el);
      });
    }
    /* ① 分桶 */
    var bucket = {};     // key -> [el...]
    var unknown = [];
    kids.forEach(function (el) {
      var k = detect(el);
      if (!k) { unknown.push(el); return; }
      (bucket[k] = bucket[k] || []).push(el);
    });
    /* ② 去重（同 key 只留第一顆，其餘移除） */
    var keep = {};
    Object.keys(bucket).forEach(function (k) {
      var arr = bucket[k];
      keep[k] = arr[0];
      for (var i = 1; i < arr.length; i++) {
        if (arr[i].parentNode) arr[i].parentNode.removeChild(arr[i]);
        log('移除重複按鈕：' + k);
      }
    });
    /* ③ 標記 class + 顯示/隱藏 + 文字 */
    Object.keys(keep).forEach(function (k) {
      var el = keep[k];
      if (!el) return;
      el.classList.add('hy-ext-btn');
      el.setAttribute('data-tabfix', k);
      if (CFG.HIDDEN[k]) el.style.setProperty('display', 'none', 'important');
      else el.style.removeProperty('display');
      applyCompact(el, k);
    });

    /* ⭐⭐ v69：常用功能搬到「當前時空」旁邊
       ──────────────────────────────────────────────────────────
       使用者要求：把「離線掛機／畫面自適應／字體／儲存進度」四顆
       搬到主標題的「當前時空」徽章右側，不必橫向捲動工具列去找。

       做法：搬到 #top-quick-slot（index.html 內預留的 span）。
       這四顆一旦搬出 .system-controls，就必須從後面的重排序列排除，
       否則 ④ 重排時會把它們抓回工具列（造成每 700ms 來回搬動）。 */
    var QUICK_KEYS = { offline: 1, adaptive: 1, font: 1, save: 1 };
    var quickSlot = document.getElementById('top-quick-slot');
    var inQuick = {};
    if (quickSlot) {
      /* ⭐ v71：先清掉插槽內的「非快捷按鈕」（例如系統連動 link），
         再依指定順序重排。
         ⚠️ 舊版先 appendChild 重排、後清理，導致清理時把剛排好的元素
            又打亂（實測順序變成 畫面→字體→儲存→離線）。
         使用者指定順序：離線 → 畫面 → 字體 → 儲存 */
      Array.prototype.slice.call(quickSlot.children).forEach(function (ch) {
        if (!ch || ch.nodeType !== 1) return;
        var k = detect(ch);
        if (!k || !QUICK_KEYS[k]) quickSlot.removeChild(ch);
      });

      var wantOrder = ['offline', 'adaptive', 'font', 'save'];
      /* ① 先把四顆都搬進插槽 */
      wantOrder.forEach(function (k) {
        var el = keep[k];
        if (!el) return;
        inQuick[k] = true;
        if (el.parentNode !== quickSlot) quickSlot.appendChild(el);
      });
      /* ② 再依序 append（appendChild 對已存在元素＝移到尾端，可保證順序） */
      wantOrder.forEach(function (k) {
        var el = keep[k];
        if (el && el.parentNode === quickSlot) quickSlot.appendChild(el);
      });

      /* 插槽內若有已隱藏的按鈕，同步套用隱藏 */
      Object.keys(QUICK_KEYS).forEach(function (k) {
        var el = keep[k];
        if (el && CFG.HIDDEN[k]) el.style.setProperty('display', 'none', 'important');
      });
      /* ⭐ v72：最終保險 —— 插槽裡只准有那四顆。
         其他腳本（例如 uiFriend6 的系統連動）可能每 2 秒又把自己插回來，
         這裡每次校正都把非白名單元素移出插槽（移到工具列尾端並隱藏）。 */
      Array.prototype.slice.call(quickSlot.children).forEach(function (ch) {
        if (!ch || ch.nodeType !== 1) return;
        var k = detect(ch);
        if (k && QUICK_KEYS[k]) return;         /* 白名單：留著 */
        ch.style.setProperty('display', 'none', 'important');
        if (ctrl && ch.parentNode === quickSlot) ctrl.appendChild(ch);
      });
    }
    /* ④ 組出目標順序
       ⚠️ 若使用者拖曳過標籤（localStorage 有存檔），改用拖曳順序為準；
          否則才套用 CFG.ORDER 的固定順序。
       ⭐ v69：這裡必須「重新取目前子元素」，不能用前面的 kids 快照 ——
          因為第三步已把離線／畫面／字體／儲存搬到快捷插槽，
          快照裡還含著它們，會被當成待排序對象抓回工具列。 */
    var liveKids = Array.prototype.slice.call(ctrl.children).filter(isEl);
    var seq = [];
    var dragged = dragOrderKeys();
    if (dragged) {
      /* ⭐ 拖曳模式：直接採用「目前 DOM 的實際順序」，一個都不搬。
         ⚠️ 舊版會先重新排列再比對，導致 seq 與現況永遠有微小差異，
            每 700ms 就搬一次 DOM —— 這就是「標籤跳動」的真正來源。
         使用者拖曳後 DOM 就是他要的順序，本檔只補未列出的新按鈕到最後。 */
      seq = liveKids.filter(function (el) {
        var k = detect(el);
        if (k && inQuick[k]) return false;     /* ⭐ v69：已在快捷區的不參與排序 */
        return !(k && keep[k] !== el);      /* 略過被去重移除的 */
      });
      /* 新出現、尚未記錄的按鈕追加到最後（不動既有順序） */
      var savedRank = {};
      (dragOrderKeys() || []).forEach(function (k, i) { savedRank[k] = i; });
      function rankOf(el) {
        var k = el.getAttribute('data-tabfix') ? ('fix:' + el.getAttribute('data-tabfix'))
          : (el.getAttribute('data-tab') ? ('tab:' + el.getAttribute('data-tab'))
            : (el.id ? ('id:' + el.id) : ('txt:' + String(el.textContent || '').trim().slice(0, 18))));
        return (savedRank[k] === undefined) ? 9999 : savedRank[k];
      }
      var known = seq.filter(function (el) { return rankOf(el) !== 9999; });
      var fresh = seq.filter(function (el) { return rankOf(el) === 9999; });
      known.sort(function (a, b) { return rankOf(a) - rankOf(b); });
      seq = known.concat(fresh);
    } else {
      CFG.ORDER.forEach(function (k) {
        /* ⭐ v69：已搬到「當前時空」旁的按鈕不再參與工具列排序 */
        if (inQuick[k]) return;
        if (keep[k]) seq.push(keep[k]);
      });
      Object.keys(keep).forEach(function (k) {
        if (inQuick[k]) return;
        if (CFG.ORDER.indexOf(k) === -1 && keep[k]) seq.push(keep[k]);
      });
      unknown.forEach(function (el) { seq.push(el); });
    }
    /* ⑤ 比對現況，不同才重排（避免無意義的 DOM 變動） */
    var cur = Array.prototype.slice.call(ctrl.children).filter(isEl);
    var same = (cur.length === seq.length) && cur.every(function (el, i) { return el === seq[i]; });
    if (!same) {
      /* 一次同步搬完 → MutationObserver 在微任務後才跑，會看到「已一致」的狀態
         且錨點相鄰關係（font 緊貼 adaptive、link 緊貼 save）全程保留 → 不會被其他腳本搬回 */
      seq.forEach(function (el) { ctrl.appendChild(el); });
      var sig = seq.map(function (el) { return el.getAttribute('data-tabfix') || '?'; }).join('>');
      if (sig !== _lastSig) {
        _lastSig = sig;
        log('已重排：' + sig);
      }
    }
    /* ⑥ 錨點相鄰檢查（若被外力拆散，這裡會在下一次 run 修回）
       ⚠️ 舊版把「系統連動(link) 必須緊貼 儲存(save)」當成條件，
          但 v71 已把 link 移出快捷插槽並隱藏 → 這個條件永遠不成立
          → 每輪都印「錨點相鄰被拆散」，把 console 刷滿。
          現在只在「畫面上的相鄰」真的壞掉時才檢查，且同一狀態只記一次。 */
    var adjOK = true;
    /* 只檢查「有顯示的」元素：隱藏的不算破壞相鄰 */
    function visibleSibling(el) {
      if (!el) return null;
      var p = el.previousElementSibling;
      while (p && p.style && p.style.display === 'none') p = p.previousElementSibling;
      return p;
    }
    if (keep.adaptive && keep.font && keep.font.offsetParent !== null) {
      if (visibleSibling(keep.font) !== keep.adaptive) adjOK = false;
    }
    if (!adjOK) {
      /* 只記錄「狀態變化」：從正常變成異常時才印一次 */
      if (!_adjWarned) {
        _adjWarned = true;
        if (CFG.VERBOSE) log('錨點相鄰被拆散（已排入下次校正）');
      }
    } else if (_adjWarned) {
      _adjWarned = false;
      if (CFG.VERBOSE) log('錨點相鄰已恢復');
    }
    return !same;
  }
  /* ══════════════════════════════════════════════════════
     ⑤ 持續校正
     ──────────────────────────────────────────────────────────
     ⚠️ 舊版無限迴圈：
         run() 會搬移 DOM 元素 → MutationObserver 偵測到 → schedule() → run()
         → 又搬 DOM → 又觸發 observer → 每秒數十次，console 被刷滿，
           並持續佔用主執行緒（與 gameConfigSpeed 的排程器互相拖累）。

     修法：
        ① 自己改 DOM 時暫停 observer（_suppress 旗標）
        ② 只在前一次變動「穩定 400ms」後才校正（debounce）
        ③ 同一簽章不重複記錄 log（避免刷屏）
        ④ 連續 3 次校正都沒有實際變動 → 進入休眠（不再自動校正）
     ══════════════════════════════════════════════════════ */
  var _pending = false;
  var _suppress = false;        /* 自己改 DOM 時暫停 observer */
  var _stableTimer = null;
  var _noChangeStreak = 0;      /* 連續無變動次數（達 3 就休眠） */
  var _asleep = false;

  function schedule() {
    if (_asleep) return;
    if (_pending) return;
    _pending = true;
    /* debounce：等 DOM 穩定 400ms 再校正，避免連續變動時反覆觸發 */
    if (_stableTimer) clearTimeout(_stableTimer);
    _stableTimer = setTimeout(function () {
      _stableTimer = null;
      _pending = false;
      if (_asleep) return;
      var changed = false;
      _suppress = true;                    /* ① 暫停 observer */
      try {
        changed = run();
      } catch (e) {
        warn('校正失敗：', e);
      }
      _suppress = false;
      /* ③ 記錄簽章，同一簽章不重複刷 log */
      if (changed) {
        _noChangeStreak = 0;
      } else {
        _noChangeStreak++;
        /* ④ 連續 3 次都沒變 → 休眠，不再自動校正 */
        if (_noChangeStreak >= 3) {
          _asleep = true;
          try { if (window.__tabFixMO) window.__tabFixMO.disconnect(); } catch (e2) { }
          log('排版已穩定，停止自動校正（如需重啟：HY.TabFix.run()）');
        }
      }
    }, 400);
  }

  function startObserver() {
    if (!window.MutationObserver || !document.body) return;
    try {
      var mo = new MutationObserver(function (muts) {
        if (_suppress) return;             /* ② 自己改 DOM 時不觸發 */
        for (var i = 0; i < muts.length; i++) {
          var m = muts[i];
          if (m.type !== 'childList') continue;
          if (!m.addedNodes || !m.addedNodes.length) continue;
          /* 只關心「新按鈕被加進容器」或「容器本身」 */
          for (var j = 0; j < m.addedNodes.length; j++) {
            var n = m.addedNodes[j];
            if (!isEl(n)) continue;
            if (n === container() || n.closest && n.closest(CFG.CONTAINER_SEL)) { schedule(); return; }
          }
        }
      });
      mo.observe(document.body, { childList: true, subtree: true });
      window.__tabFixMO = mo;
    } catch (e) { warn('MutationObserver 失敗：', e); }
  }
  /* ══════════════════════════════════════════════════════
     ⑥ 對外 API
     ══════════════════════════════════════════════════════ */
  window.HY.TabFix = {
    version: '1.0',
    ready: false,
    run: function () { return run(); },
    config: function (o) { if (o) Object.keys(o).forEach(function (k) { CFG[k] = o[k]; }); injectCSS(); return CFG; },
    order: function (a) {
      if (Array.isArray(a) && a.length) { CFG.ORDER = a.slice(); run(); }
      return CFG.ORDER.slice();
    },
    hide: function (k) { if (k) { CFG.HIDDEN[k] = 1; run(); } return Object.keys(CFG.HIDDEN); },
    show: function (k) { if (k) { delete CFG.HIDDEN[k]; run(); } return Object.keys(CFG.HIDDEN); },
    compact: function (v) {
      CFG.COMPACT = (v !== false);
      run();
      return CFG.COMPACT;
    },
    /** 列出所有按鈕的實際尺寸（診斷寬條用） */
    audit: function () {
      var ctrl = container();
      if (!ctrl) { warn('找不到容器 ' + CFG.CONTAINER_SEL); return []; }
      var rows = [];
      Array.prototype.slice.call(ctrl.children).filter(isEl).forEach(function (el, i) {
        var r = el.getBoundingClientRect();
        rows.push({
          '#': i,
          key: el.getAttribute('data-tabfix') || '（未知）',
          id: el.id || '',
          text: norm(txtOf(el)).slice(0, 14),
          寬: Math.round(r.width),
          高: Math.round(r.height),
          flexGrow: window.getComputedStyle(el).flexGrow,
          display: window.getComputedStyle(el).display
        });
      });
      console.log('%c=== TabFix 按鈕尺寸稽核 ===', 'color:#34d399;font-weight:bold');
      console.table(rows);
      console.log('提示：寬度特別大的那顆，就是原本的「寬條」問題來源（已由 flex:0 0 auto 修正）');
      return rows;
    },
    status: function () {
      var ctrl = container();
      var keys = [];
      if (ctrl) {
        Array.prototype.slice.call(ctrl.children).filter(isEl).forEach(function (el) {
          keys.push(el.getAttribute('data-tabfix') || (el.id ? '#' + el.id : norm(txtOf(el)).slice(0, 10)));
        });
      }
      return {
        version: '1.0',
        ready: window.HY.TabFix.ready,
        container: ctrl ? (ctrl.className || ctrl.id || ctrl.tagName) : null,
        containerFound: !!ctrl,
        order: CFG.ORDER.slice(),
        current: keys,
        hidden: Object.keys(CFG.HIDDEN),
        compact: CFG.COMPACT,
        observer: !!window.__tabFixMO,
        styleInjected: !!document.getElementById('tabfix-style')
      };
    }
  };
  /* ══════════════════════════════════════════════════════
     ⑦ 啟動
     ══════════════════════════════════════════════════════ */
  function boot() {
    if (!document.body) return false;
    if (!window.HY.TabFix.ready) {
      injectCSS();
      startObserver();
      window.HY.TabFix.ready = true;
      log('已啟動（容器：' + CFG.CONTAINER_SEL + '｜順序：' + CFG.ORDER.join(' > ') + '）');
    }
    run();
    return true;
  }
  if (document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(boot, 200);
  else window.addEventListener('DOMContentLoaded', function () { setTimeout(boot, 200); });
  window.addEventListener('load', function () { setTimeout(boot, 600); });
