    function isAllowedLabel(l) { return !!ALLOWED_LABELS[l]; }

    /* ══════════════════════════════════════════════════════════
       ⭐ 等級縮放
       ──────────────────────────────────────────────────────────
       本作的基底裝備數值隨需求等級大幅成長：
         Lv.1   鐵戒指      atk 12
         Lv.25  寶鑽戒指    atk 35
         Lv.80  雙玉戒指    atk 140 / maxHp 750
         Lv.240 朱砂之戒    atk 950 / maxHp 6000
         Lv.290 破碎虛空之戒 atk 2000 / maxHp 12000
       如果 PoE 詞綴用固定倍率，Lv.1 裝備會加 1800 血（荒謬），
       Lv.290 裝備只加 1800 血（無感）。
       因此改用「相對等級係數」：以 Lv.80 為基準 1.0，
       低等級壓縮、高等級放大，並設上下限避免極端值。
       ══════════════════════════════════════════════════════════ */
    function levelFactor(reqLv) {
        var lv = (typeof reqLv === 'number' && isFinite(reqLv) && reqLv > 0) ? reqLv : 1;
        /* 對數曲線：lv 1 → 0.25、lv 80 → 1.0、lv 290 → 2.4
           下限從 0.12 提高到 0.25：原本 Lv.1 裝備的詞綴只有 40 血，
           比舊池的 T5（50~110）還弱，玩家會覺得「有詞綴跟沒有一樣」。 */
        var f = 0.25 + 0.75 * (Math.log(1 + lv / 8) / Math.log(1 + 80 / 8));
        return Math.max(0.25, Math.min(2.4, f));
    }

    /* ══════════════════════════════════════════════════════════
       規則表
       ──────────────────────────────────────────────────────────
       m : 比對的正則（對「已把數字換成 #」的樣板）
       k : 屬性鍵
       l : 中文名稱
       u : 單位（'%' 或 ''）
       scale : 可選，值域縮放係數（本作數值體系與 PoE 不同，
               某些詞綴需要放大或縮小才不會過強／過弱）
       ══════════════════════════════════════════════════════════ */

