  window.HY.PoeCurrencyIcons.v = 3;
  window.HY.PoeCurrencyIcons.ready = true;
  window.HY.PoeCurrencyIcons.paint = paint;
  window.HY.PoeCurrencyIcons.debug = debug;
  window.HY.PoeCurrencyIcons.idFile = ID_FILE;
  window.HY.PoeCurrencyIcons.localBase = LOCAL_BASE;
  window.HY.PoeCurrencyIcons.cdnBase = CDN_BASE;
