        if ((Date.now() - st.lastCallAt) > CFG.windowMs) return;
        st.autoResumed += 1;
        try { btn.click(); } catch (e) { st.lastErr = 'resume click: ' + e; }
        log('auto battle re-armed (a settle call coincided with the flip)');
