        iconSlot: st.applied.iconSlot || DEFAULTS.iconSlot,
        iconOrb:  st.applied.iconOrb  || DEFAULTS.iconOrb,
        fontCell: st.applied.fontCell || DEFAULTS.fontCell,
        fontOrb:  st.applied.fontOrb  || DEFAULTS.fontOrb
